-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_7c7cd07b5ae5a4', 'subj_chem', 'weak-acids-buffers', 'Weak acids and buffers', 'K_a = \frac{[\text{H}^+][\text{A}^-]}{[\text{HA}]}, \quad K_aK_b = K_w, \quad \text{pH} = \text{p}K_a + \log\frac{[\text{A}^-]}{[\text{HA}]}', 'Acid dissociation constant, the conjugate-pair relation, and the Henderson–Hasselbalch equation for buffers.', '[{"symbol":"K_a","meaning":"acid dissociation constant"},{"symbol":"\\text{p}K_a","meaning":"−log Ka"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_15e1fc516df8df', 'subj_chem', 'electrochemistry', 'Cell potentials', 'E^\circ_{cell} = E^\circ_{cathode} - E^\circ_{anode}, \quad \Delta G^\circ = -nFE^\circ, \quad E = E^\circ - \frac{0.0592}{n}\log Q', 'Standard cell potential, its link to free energy (F = 96,485 C/mol), and the Nernst equation at 25 °C.', '[{"symbol":"n","meaning":"moles of electrons transferred"},{"symbol":"F","meaning":"Faraday constant","unit":"C/mol"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_fc4a4b7ae1d428', 'subj_chem', 'colligative', 'Colligative properties', '\Delta T_f = iK_fm, \quad \Delta T_b = iK_bm, \quad \Pi = iMRT', 'Freezing-point depression, boiling-point elevation and osmotic pressure; i is the van ''t Hoff factor and m the molality.', '[{"symbol":"m","meaning":"molality","unit":"mol/kg"},{"symbol":"i","meaning":"van ''t Hoff factor"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_ba5e448d9ff34f', 'subj_chem', 'rate-laws', 'Rate laws', '\text{rate} = k[A]^m[B]^n, \quad \ln[A] = \ln[A]_0 - kt, \quad t_{1/2} = \frac{\ln 2}{k}', 'Differential rate law and the first-order integrated rate law and half-life.', '[{"symbol":"k","meaning":"rate constant"},{"symbol":"m, n","meaning":"reaction orders"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_d3accd125b57a3', 'subj_chem', 'free-energy', 'Gibbs free energy', '\Delta G = \Delta H - T\Delta S, \quad \Delta G^\circ = -RT\ln K, \quad \Delta G = \Delta G^\circ + RT\ln Q', 'Free energy predicts thermodynamic favorability; ΔG° is related to the equilibrium constant.', '[{"symbol":"\\Delta S","meaning":"entropy change","unit":"J/(mol·K)"},{"symbol":"R","meaning":"8.314 J/(mol·K)"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_bedd8b8bc9dc67', 'subj_chem', 'beer-lambert', 'Beer–Lambert law', 'A = \varepsilon bc', 'Absorbance is proportional to molar absorptivity, path length and concentration.', '[{"symbol":"A","meaning":"absorbance"},{"symbol":"b","meaning":"path length","unit":"cm"},{"symbol":"c","meaning":"concentration","unit":"M"}]', 'published');

-- Lesson: beer-lambert-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_269d79e77dc42a', 'beer-lambert-law', 'Beer–Lambert law', 'Use A = εbc to relate absorbance to concentration, build and use calibration curves, and relate absorbance to transmittance.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b02845dfa06c2a', 'les_269d79e77dc42a', 1, 'Use A = εbc and identify each variable.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_383d5c8875e745', 'les_269d79e77dc42a', 2, 'Use a calibration curve to find an unknown concentration.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad237d656aaccc', 'les_269d79e77dc42a', 3, 'Relate absorbance to transmittance: A = −log T.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b02845dfa06c2a', 'les_269d79e77dc42a', 'learn', 1, 'definition', '{"term":"The law","body":"$A = \\varepsilon bc$: absorbance is proportional to concentration c (M), path length b (cm, usually 1) and molar absorptivity ε, which depends on the substance and wavelength. Measure at the wavelength of maximum absorbance for best sensitivity. $T = 10^{-A}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_383d5c8875e745', 'les_269d79e77dc42a', 'learn', 2, 'worked_example', '{"title":"ε = 5000 M⁻¹cm⁻¹, b = 1.00 cm","steps":[{"latex":"A = 5000(1.00)(1.0\\times10^{-4}) = 0.50","explanation":"For c = 1.0 × 10⁻⁴ M."},{"latex":"T = 10^{-0.50} \\approx 32\\%","explanation":""},{"latex":"c = \\tfrac{0.36}{5000} = 7.2\\times10^{-5}\\ \\text{M}","explanation":"An unknown with A = 0.36."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad237d656aaccc', 'les_269d79e77dc42a', 'experiment', 3, 'activity', '{"activity":"beer-lambert","title":"Absorbance and concentration","params":{"concentration":0.0001,"path":1,"absorptivity":5000}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47c1e279b3e828', 'les_269d79e77dc42a', 'learn', 4, 'callout', '{"tone":"warning","title":"Common lab errors","body":"Fingerprints or bubbles on the cuvette raise the absorbance, so the calculated concentration comes out too high. A different-width cuvette changes b."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2908a6a0ba0db5', 'les_269d79e77dc42a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Blood glucose meters, water-quality tests and DNA concentration measurements all use absorbance."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b02845dfa06c2a', 'les_269d79e77dc42a', 1, 'practice', 'numeric', 2, 'A solution with ε = 12,000 M⁻¹cm⁻¹ in a 1.00 cm cell has A = 0.60. Find c, in units of $10^{-5}$ M.', '{"answer":5}', '[]', '$\frac{0.60}{12{,}000}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_383d5c8875e745', 'les_269d79e77dc42a', 2, 'practice', 'numeric', 2, 'Find the transmittance for A = 1.0, in percent.', '{"answer":10,"unit":"%"}', '[]', '$10^{-1}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad237d656aaccc', 'les_269d79e77dc42a', 3, 'practice', 'multiple_choice', 2, 'Doubling the path length doubles the…', '{"choices":["concentration","absorbance","transmittance","ε"],"answer":1}', '[]', '$A \propto b$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47c1e279b3e828', 'les_269d79e77dc42a', 4, 'review', 'multiple_choice', 3, 'A smudged cuvette makes the calculated concentration…', '{"choices":["too low","too high","unchanged","zero"],"answer":1}', '[]', 'Extra apparent absorbance.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_269d79e77dc42a', (SELECT id FROM concepts WHERE slug = 'solutions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_269d79e77dc42a', (SELECT id FROM formulas WHERE slug = 'beer-lambert'), 1);

-- Lesson: bond-enthalpies
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_11b9330fbff91a', 'bond-enthalpies', 'Bond enthalpies', 'Estimate ΔH_rxn from average bond enthalpies: energy to break reactant bonds minus energy released forming product bonds.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_431011af86242f', 'les_11b9330fbff91a', 1, 'Count the bonds broken and formed using Lewis structures.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_03e30f1408124d', 'les_11b9330fbff91a', 2, 'Estimate ΔH ≈ Σ(bonds broken) − Σ(bonds formed).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_73737403460103', 'les_11b9330fbff91a', 3, 'Explain why bond-enthalpy estimates differ from measured values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_431011af86242f', 'les_11b9330fbff91a', 'learn', 1, 'definition', '{"term":"The estimate","body":"$\\Delta H \\approx \\sum D(\\text{broken}) - \\sum D(\\text{formed})$. Average values (kJ/mol): C–H 413, O=O 498, C=O (in CO₂) 799, O–H 463, H–H 436, Cl–Cl 243, H–Cl 431."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03e30f1408124d', 'les_11b9330fbff91a', 'learn', 2, 'worked_example', '{"title":"CH₄ + 2O₂ → CO₂ + 2H₂O(g)","steps":[{"latex":"\\text{broken: } 4(413) + 2(498) = 2648\\ \\text{kJ}","explanation":""},{"latex":"\\text{formed: } 2(799) + 4(463) = 3450\\ \\text{kJ}","explanation":""},{"latex":"\\Delta H \\approx 2648 - 3450 = -802\\ \\text{kJ}","explanation":"The measured value is −802 kJ for water vapor."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73737403460103', 'les_11b9330fbff91a', 'learn', 3, 'callout', '{"tone":"note","title":"Why only estimates","body":"Table values are averages over many molecules; a C–H bond''s strength depends on its neighbors. Formation enthalpies give more accurate results."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44eaa2d414e376', 'les_11b9330fbff91a', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Quick estimates of fuel energies, and checking whether proposed reactions are energetically reasonable."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_431011af86242f', 'les_11b9330fbff91a', 1, 'practice', 'numeric', 2, 'Estimate ΔH for H₂ + Cl₂ → 2HCl.', '{"answer":-183,"unit":"kJ"}', '[]', '$436 + 243 - 2(431)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03e30f1408124d', 'les_11b9330fbff91a', 2, 'practice', 'numeric', 3, 'Estimate ΔH for 2H₂ + O₂ → 2H₂O(g).', '{"answer":-482,"unit":"kJ"}', '[]', '$2(436) + 498 - 4(463)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_73737403460103', 'les_11b9330fbff91a', 3, 'practice', 'multiple_choice', 2, 'A reaction is exothermic when the bonds formed are…', '{"choices":["weaker than those broken","stronger than those broken","the same","fewer"],"answer":1}', '[]', 'More energy released than absorbed.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_44eaa2d414e376', 'les_11b9330fbff91a', 4, 'review', 'multiple_choice', 3, 'Bond-enthalpy estimates are least reliable because…', '{"choices":["bonds don''t exist","table values are averages across many compounds","they ignore mass","they''re always zero"],"answer":1}', '[]', 'Each bond''s environment matters.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_11b9330fbff91a', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));

-- Lesson: bond-potential-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a6a6da6ec42cda', 'bond-potential-energy', 'Intramolecular force and potential energy', 'Read potential-energy curves for bond formation to find bond length and bond energy, and connect them to bond order and atomic size.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7cab3580165233', 'les_a6a6da6ec42cda', 1, 'Describe how potential energy changes as two atoms approach.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f82f0d5177111', 'les_a6a6da6ec42cda', 2, 'Read bond length and bond energy from a potential-energy curve.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ece2421f8f9f32', 'les_a6a6da6ec42cda', 3, 'Relate bond order and atomic radius to bond length and strength, and use Coulomb''s law for ionic bonds.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7cab3580165233', 'les_a6a6da6ec42cda', 'learn', 1, 'definition', '{"term":"The curve","body":"Far apart, two atoms don''t interact (energy zero). As they approach, attraction lowers the energy; too close, nuclear repulsion raises it sharply. The minimum sits at the bond length, and its depth is the bond energy, the energy needed to break the bond."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f82f0d5177111', 'les_a6a6da6ec42cda', 'learn', 2, 'worked_example', '{"title":"For H₂, the minimum is at 74 pm and −436 kJ/mol","steps":[{"latex":"r_{min} = 74\\ \\text{pm}","explanation":"The bond length."},{"latex":"D = 436\\ \\text{kJ/mol}","explanation":"The bond energy: the depth of the well."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ece2421f8f9f32', 'les_a6a6da6ec42cda', 'learn', 3, 'definition', '{"term":"Trends","body":"Higher bond order means shorter and stronger: C–C 154 pm and 347 kJ/mol; C=C 134 pm and 614 kJ/mol; C≡C 120 pm and 839 kJ/mol. Larger atoms make longer, weaker bonds (H–F stronger than H–I). For ions, Coulomb''s law $E \\propto \\frac{q_1q_2}{r}$ means higher charges and smaller ions bond more strongly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ffac5531171c2', 'les_a6a6da6ec42cda', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Infrared spectroscopy probes the curvature of these wells; the strong N≡N bond is why making fertilizer from air takes so much energy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7cab3580165233', 'les_a6a6da6ec42cda', 1, 'practice', 'multiple_choice', 2, 'On a potential-energy curve, the bond length is where…', '{"choices":["energy is zero","energy is minimum","repulsion begins","the curve ends"],"answer":1}', '[]', 'The most stable separation.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f82f0d5177111', 'les_a6a6da6ec42cda', 2, 'practice', 'multiple_choice', 2, 'Which bond is longest?', '{"choices":["H–F","H–Cl","H–Br","H–I"],"answer":3}', '[]', 'Iodine is largest.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ece2421f8f9f32', 'les_a6a6da6ec42cda', 3, 'practice', 'numeric', 2, 'How much energy (kJ) breaks 2.00 mol of H₂ bonds (436 kJ/mol)?', '{"answer":872,"unit":"kJ"}', '[]', '$2 \times 436$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ffac5531171c2', 'les_a6a6da6ec42cda', 4, 'review', 'multiple_choice', 3, 'Compared with C–O, a C=O bond is…', '{"choices":["longer and weaker","shorter and stronger","the same length","longer and stronger"],"answer":1}', '[]', 'Higher bond order.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a6a6da6ec42cda', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: buffers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_990742f8b49d8a', 'buffers', 'Buffers', 'Explain how a weak acid and its conjugate base resist pH changes, use the Henderson–Hasselbalch equation, and calculate pH after adding strong acid or base.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d2bfeb21410d06', 'les_990742f8b49d8a', 1, 'Identify buffer pairs and explain how they neutralize added acid or base.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b96e7abd9eaa8f', 'les_990742f8b49d8a', 2, 'Use pH = pKa + log([A⁻]/[HA]).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_53622ad4768d06', 'les_990742f8b49d8a', 3, 'Calculate pH after adding strong acid or base: react first, then apply Henderson–Hasselbalch.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2bfeb21410d06', 'les_990742f8b49d8a', 'learn', 1, 'definition', '{"term":"How buffers work","body":"A buffer contains a weak acid and its conjugate base in similar amounts. Added OH⁻ is consumed by HA (HA + OH⁻ → A⁻ + H₂O); added H⁺ is consumed by A⁻. Only the ratio $\\frac{[\\text{A}^-]}{[\\text{HA}]}$ changes, slowly, so the pH barely moves."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b96e7abd9eaa8f', 'les_990742f8b49d8a', 'learn', 2, 'definition', '{"term":"Henderson–Hasselbalch","body":"$\\text{pH} = \\text{p}K_a + \\log\\frac{[\\text{A}^-]}{[\\text{HA}]}$. Equal amounts give pH = pKa. A buffer works best within about ±1 of its pKa."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_53622ad4768d06', 'les_990742f8b49d8a', 'learn', 3, 'worked_example', '{"title":"1.00 L with 0.10 mol acetic acid and 0.10 mol acetate (pKa 4.74), after adding 0.010 mol NaOH","steps":[{"latex":"n_{\\text{HA}} = 0.10 - 0.010 = 0.090\\ \\text{mol}","explanation":"React first: OH⁻ converts HA to A⁻."},{"latex":"n_{\\text{A}^-} = 0.10 + 0.010 = 0.11\\ \\text{mol}","explanation":""},{"latex":"\\text{pH} = 4.74 + \\log\\tfrac{0.11}{0.090} \\approx 4.83","explanation":"Up only 0.09; pure water would jump from 7 to 12."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8dd4ce5e0b9b06', 'les_990742f8b49d8a', 'experiment', 4, 'activity', '{"activity":"buffer","title":"Buffer vs pure water","params":{"acid":0.1,"base":0.1,"added":0.01}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a741cb0e3bfdbf', 'les_990742f8b49d8a', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Push the added base past 0.10 mol: the acetic acid runs out and the buffer''s pH shoots up. That limit is the buffer capacity."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b6d856d76bd81', 'les_990742f8b49d8a', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Blood stays near pH 7.4 with the carbonic acid–bicarbonate buffer; shampoos, eye drops and lab media are all buffered."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d2bfeb21410d06', 'les_990742f8b49d8a', 1, 'practice', 'numeric', 2, 'Find the pH of a buffer with 0.15 M acetate and 0.10 M acetic acid, to two decimal places.', '{"answer":4.92,"tolerance":0.01}', '[]', '$4.74 + \log 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b96e7abd9eaa8f', 'les_990742f8b49d8a', 2, 'practice', 'numeric', 3, 'To 1.00 L of 0.20 M NH₃ / 0.20 M NH₄⁺ (pKa 9.25) you add 0.050 mol HCl. Find the pH, to two decimal places.', '{"answer":9.03,"tolerance":0.01}', '[]', 'NH₃ 0.15, NH₄⁺ 0.25: $9.25 + \log\frac{0.15}{0.25}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_53622ad4768d06', 'les_990742f8b49d8a', 3, 'practice', 'multiple_choice', 2, 'Which pair makes a buffer?', '{"choices":["HCl / NaCl","HNO₂ / NaNO₂","NaOH / NaCl","HCl / NaOH"],"answer":1}', '[]', 'A weak acid and its conjugate base.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8dd4ce5e0b9b06', 'les_990742f8b49d8a', 4, 'review', 'multiple_choice', 3, 'For a buffer at pH 5.0, the best choice is a weak acid with pKa near…', '{"choices":["2","5","9","14"],"answer":1}', '[]', 'pH = pKa at maximum capacity.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_990742f8b49d8a', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_990742f8b49d8a', (SELECT id FROM formulas WHERE slug = 'weak-acids-buffers'), 1);

-- Lesson: calculating-k
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d5e8091af1add8', 'calculating-k', 'Calculating the equilibrium constant', 'Calculate K from equilibrium concentrations, from initial amounts plus one equilibrium measurement, and convert between Kc and Kp.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9eeea01e93e6d9', 'les_d5e8091af1add8', 1, 'Calculate K by substituting equilibrium concentrations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_708e940db62036', 'les_d5e8091af1add8', 2, 'Use an ICE table when only one equilibrium concentration is known.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_76c5366a2d030c', 'les_d5e8091af1add8', 3, 'Convert Kp = Kc(RT)^Δn.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9eeea01e93e6d9', 'les_d5e8091af1add8', 'learn', 1, 'worked_example', '{"title":"H₂ + I₂ ⇌ 2HI: start with 1.00 M of each reactant; at equilibrium [HI] = 1.56 M","steps":[{"latex":"2x = 1.56 \\Rightarrow x = 0.78","explanation":""},{"latex":"[\\text{H}_2] = [\\text{I}_2] = 1.00 - 0.78 = 0.22\\ \\text{M}","explanation":""},{"latex":"K = \\tfrac{(1.56)^2}{(0.22)^2} \\approx 50","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_708e940db62036', 'les_d5e8091af1add8', 'learn', 2, 'definition', '{"term":"Kp and Kc","body":"For gases, $K_p = K_c(RT)^{\\Delta n}$, where Δn is moles of gaseous products minus gaseous reactants and R = 0.08206 L·atm/(mol·K)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_76c5366a2d030c', 'les_d5e8091af1add8', 'learn', 3, 'worked_example', '{"title":"2SO₂ + O₂ ⇌ 2SO₃, Kc = 320 at 1000 K","steps":[{"latex":"\\Delta n = 2 - 3 = -1","explanation":""},{"latex":"K_p = \\tfrac{320}{0.08206(1000)} \\approx 3.9","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9bf8aad01202b1', 'les_d5e8091af1add8', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Thermodynamic databases list K values measured this way, and they''re used to design every chemical plant."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9eeea01e93e6d9', 'les_d5e8091af1add8', 1, 'practice', 'numeric', 2, 'For PCl₅ ⇌ PCl₃ + Cl₂ at equilibrium, [PCl₅] = 0.20 M and [PCl₃] = [Cl₂] = 0.10 M. Find K.', '{"answer":0.05,"tolerance":0.0001}', '[]', '$\frac{0.01}{0.20}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_708e940db62036', 'les_d5e8091af1add8', 2, 'practice', 'numeric', 3, 'A + B ⇌ C starts with 1.0 M A and B; at equilibrium [C] = 0.40 M. Find K, to two decimal places.', '{"answer":1.11,"tolerance":0.01}', '[]', '$\frac{0.40}{0.60^2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_76c5366a2d030c', 'les_d5e8091af1add8', 3, 'practice', 'multiple_choice', 2, 'When Δn = 0 for a gas reaction,…', '{"choices":["Kp = Kc","Kp = 0","Kp = 1/Kc","Kp = RT"],"answer":0}', '[]', '$(RT)^0 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9bf8aad01202b1', 'les_d5e8091af1add8', 4, 'review', 'multiple_choice', 3, 'A K value depends on…', '{"choices":["starting concentrations","temperature","catalysts","container shape"],"answer":1}', '[]', 'Only temperature changes K.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d5e8091af1add8', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d5e8091af1add8', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: catalysis
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3342f8fefb2f24', 'catalysis', 'Catalysis', 'Explain how catalysts lower activation energy through new mechanisms, compare homogeneous, heterogeneous and enzyme catalysis, and estimate rate increases.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_92dd5f51804258', 'les_3342f8fefb2f24', 1, 'Explain that a catalyst provides a new mechanism with lower Eₐ and is regenerated.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f17d616dae348', 'les_3342f8fefb2f24', 2, 'Distinguish homogeneous, heterogeneous (surface) and enzyme catalysis.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_57c06d0d067113', 'les_3342f8fefb2f24', 3, 'Estimate the rate increase from a lower Eₐ: k₂/k₁ = e^(ΔEₐ/RT).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92dd5f51804258', 'les_3342f8fefb2f24', 'learn', 1, 'definition', '{"term":"How catalysts work","body":"A catalyst opens a different pathway with lower activation energy. It speeds the forward and reverse reactions equally, so it doesn''t change ΔH or the equilibrium position, only how fast equilibrium is reached. It''s consumed in one step and regenerated in a later one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f17d616dae348', 'les_3342f8fefb2f24', 'learn', 2, 'definition', '{"term":"Kinds","body":"Homogeneous: same phase as the reactants (Cl atoms destroying ozone). Heterogeneous: a surface where reactants adsorb and bonds weaken (Pt in catalytic converters). Enzymes: protein catalysts whose active sites bind specific substrates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57c06d0d067113', 'les_3342f8fefb2f24', 'learn', 3, 'worked_example', '{"title":"A catalyst lowers Eₐ from 75 to 50 kJ/mol at 298 K","steps":[{"latex":"\\tfrac{k_{cat}}{k} = e^{25{,}000/(8.314\\cdot298)} \\approx 2.4\\times10^4","explanation":"About 24,000 times faster."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f773ba3ff47b4c', 'les_3342f8fefb2f24', 'experiment', 4, 'activity', '{"activity":"kinetics","title":"Lower Eₐ, faster reaction","params":{"order":"1","k":0.1,"A0":1,"temperature":298,"Ea":30}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e403fe90178140', 'les_3342f8fefb2f24', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Catalytic converters, the Haber process (iron catalyst), enzymes in laundry detergents and nearly every reaction in your cells."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_92dd5f51804258', 'les_3342f8fefb2f24', 1, 'practice', 'numeric', 3, 'A catalyst lowers Eₐ by 10 kJ/mol at 300 K. By what factor does k increase, to one decimal place?', '{"answer":55.1,"tolerance":0.2}', '[]', '$e^{10{,}000/(8.314\cdot300)} \approx 55$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f17d616dae348', 'les_3342f8fefb2f24', 2, 'practice', 'multiple_choice', 2, 'A catalyst changes…', '{"choices":["ΔH","the equilibrium constant","the activation energy","the products"],"answer":2}', '[]', 'Only the pathway.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_57c06d0d067113', 'les_3342f8fefb2f24', 3, 'practice', 'multiple_choice', 2, 'Platinum in a catalytic converter is…', '{"choices":["homogeneous","heterogeneous","an enzyme","a reactant"],"answer":1}', '[]', 'A solid surface with gas reactants.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f773ba3ff47b4c', 'les_3342f8fefb2f24', 4, 'review', 'multiple_choice', 3, 'In a mechanism, a catalyst appears…', '{"choices":["only as a reactant","first as a reactant, later as a product","only as a product","as an intermediate"],"answer":1}', '[]', 'It''s regenerated.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3342f8fefb2f24', (SELECT id FROM concepts WHERE slug = 'kinetics'));

-- Lesson: chromatography-separation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e8b5c4c8c6b56f', 'chromatography-separation', 'Separation of solutions and mixtures; chromatography', 'Separate mixtures by distillation and chromatography, compute Rf values, and explain separations with intermolecular forces and polarity.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_06f4fc82b4e05e', 'les_e8b5c4c8c6b56f', 1, 'Explain how distillation separates liquids by boiling point (IMF strength).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad5111171b4458', 'les_e8b5c4c8c6b56f', 2, 'Compute Rf = distance traveled by the spot / distance traveled by the solvent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7e4592402d729f', 'les_e8b5c4c8c6b56f', 3, 'Predict the order of separation from polarity of the components, the mobile phase and the stationary phase.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_06f4fc82b4e05e', 'les_e8b5c4c8c6b56f', 'learn', 1, 'definition', '{"term":"Chromatography","body":"A mixture is carried by a moving solvent (mobile phase) over a surface (stationary phase). Components that interact more with the stationary phase move more slowly. $R_f = \\frac{d_{spot}}{d_{solvent}}$ is between 0 and 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad5111171b4458', 'les_e8b5c4c8c6b56f', 'learn', 2, 'worked_example', '{"title":"A spot moves 3.2 cm while the solvent front moves 8.0 cm","steps":[{"latex":"R_f = \\tfrac{3.2}{8.0} = 0.40","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e4592402d729f', 'les_e8b5c4c8c6b56f', 'learn', 3, 'definition', '{"term":"Polarity rules","body":"On polar paper with a nonpolar solvent, nonpolar components move farther (higher Rf); polar ones stick to the paper. Reverse the polarities and the order reverses."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c7234460091758', 'les_e8b5c4c8c6b56f', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gas chromatography in drug testing, ink analysis in forensics, and fractional distillation of crude oil."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_06f4fc82b4e05e', 'les_e8b5c4c8c6b56f', 1, 'practice', 'numeric', 2, 'A dye travels 4.5 cm; the solvent front travels 7.5 cm. Find Rf.', '{"answer":0.6}', '[]', '$\frac{4.5}{7.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad5111171b4458', 'les_e8b5c4c8c6b56f', 2, 'practice', 'multiple_choice', 2, 'On a nonpolar (reversed-phase) plate with water as the solvent, which component moves farthest?', '{"choices":["a nonpolar hydrocarbon","a very polar dye","they all move the same","none move"],"answer":1}', '[]', 'The polar dye prefers the polar mobile phase and isn''t held by the nonpolar surface.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7e4592402d729f', 'les_e8b5c4c8c6b56f', 3, 'practice', 'multiple_choice', 2, 'Distillation separates components by differences in…', '{"choices":["color","boiling point","mass","charge"],"answer":1}', '[]', 'Which reflects IMF strength.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c7234460091758', 'les_e8b5c4c8c6b56f', 4, 'review', 'multiple_choice', 3, 'A component with a high Rf on polar paper with a nonpolar solvent is likely…', '{"choices":["very polar","nonpolar","ionic","insoluble"],"answer":1}', '[]', 'It prefers the nonpolar mobile phase.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e8b5c4c8c6b56f', (SELECT id FROM concepts WHERE slug = 'solutions'));

-- Lesson: colligative-properties
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_361bf45ed60fd9', 'colligative-properties', 'Colligative properties', 'Use molality and the van ''t Hoff factor to compute freezing-point depression, boiling-point elevation and osmotic pressure.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ab26d343f9cc2e', 'les_361bf45ed60fd9', 1, 'Calculate molality, m = mol solute / kg solvent.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b6133576621f69', 'les_361bf45ed60fd9', 2, 'Use the van ''t Hoff factor i for ionic solutes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bedf1e9bf06488', 'les_361bf45ed60fd9', 3, 'Compute ΔT_f = iK_fm, ΔT_b = iK_bm and Π = iMRT.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab26d343f9cc2e', 'les_361bf45ed60fd9', 'learn', 1, 'definition', '{"term":"Counting particles","body":"Colligative properties depend only on how many solute particles there are, not what they are. Molality $m = \\frac{\\text{mol solute}}{\\text{kg solvent}}$ doesn''t change with temperature. The van ''t Hoff factor $i$ counts particles per formula unit: 1 for sugar, about 2 for NaCl, about 3 for CaCl₂."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6133576621f69', 'les_361bf45ed60fd9', 'learn', 2, 'definition', '{"term":"The effects","body":"Freezing point drops: $\\Delta T_f = iK_fm$ (water $K_f = 1.86$ °C/m). Boiling point rises: $\\Delta T_b = iK_bm$ ($K_b = 0.512$ °C/m). Osmotic pressure: $\\Pi = iMRT$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bedf1e9bf06488', 'les_361bf45ed60fd9', 'learn', 3, 'worked_example', '{"title":"58.44 g of NaCl dissolved in 500. g of water","steps":[{"latex":"m = \\tfrac{1.00\\ \\text{mol}}{0.500\\ \\text{kg}} = 2.00\\ m","explanation":""},{"latex":"\\Delta T_f = 2(1.86)(2.00) = 7.44\\ °\\text{C}","explanation":""},{"latex":"T_f = -7.44\\ °\\text{C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f354a979773f1d', 'les_361bf45ed60fd9', 'learn', 4, 'worked_example', '{"title":"Osmotic pressure of 0.15 M NaCl at body temperature (310 K)","steps":[{"latex":"\\Pi = 2(0.15)(0.08206)(310) \\approx 7.6\\ \\text{atm}","explanation":"Why IV fluids must match blood''s concentration."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d6b401c3fbb98', 'les_361bf45ed60fd9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Road salt, antifreeze, salting pasta water (a small effect, actually), and the swelling or shrinking of cells in the wrong solution."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ab26d343f9cc2e', 'les_361bf45ed60fd9', 1, 'practice', 'numeric', 2, 'Find the freezing point of 1.00 m NaCl in water.', '{"answer":-3.72,"tolerance":0.01,"unit":"°C"}', '[]', '$2(1.86)(1.00)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b6133576621f69', 'les_361bf45ed60fd9', 2, 'practice', 'numeric', 2, 'Find the boiling point of 0.50 m glucose in water, to two decimal places.', '{"answer":100.26,"tolerance":0.01,"unit":"°C"}', '[]', '$0.512(0.50) = 0.256$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bedf1e9bf06488', 'les_361bf45ed60fd9', 3, 'practice', 'multiple_choice', 2, 'Which lowers water''s freezing point most, at the same molality?', '{"choices":["glucose","NaCl","CaCl₂","ethanol"],"answer":2}', '[]', 'i ≈ 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f354a979773f1d', 'les_361bf45ed60fd9', 4, 'review', 'multiple_choice', 3, 'Molality is preferred over molarity here because…', '{"choices":["it''s easier to say","it doesn''t change with temperature","it uses liters","it counts ions"],"answer":1}', '[]', 'Mass doesn''t expand with heat.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_361bf45ed60fd9', (SELECT id FROM concepts WHERE slug = 'solutions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_361bf45ed60fd9', (SELECT id FROM formulas WHERE slug = 'colligative'), 1);

-- Lesson: common-ion-effect
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_773f682a836d66', 'common-ion-effect', 'Common-ion effect', 'Explain and calculate how a common ion lowers the solubility of a salt or the ionization of a weak acid.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6ffbf46bf5fe93', 'les_773f682a836d66', 1, 'Explain the common-ion effect with Le Châtelier''s principle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_083a8b7fdd4b21', 'les_773f682a836d66', 2, 'Calculate reduced solubility in a solution containing a common ion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_51acd917cdfc89', 'les_773f682a836d66', 3, 'Connect the effect to buffers (a weak acid with its conjugate base).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ffbf46bf5fe93', 'les_773f682a836d66', 'learn', 1, 'definition', '{"term":"The effect","body":"Adding an ion already in an equilibrium shifts it away from that ion. A salt dissolves less in a solution that already contains one of its ions, and a weak acid ionizes less when its conjugate base is present (the basis of buffers)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_083a8b7fdd4b21', 'les_773f682a836d66', 'learn', 2, 'worked_example', '{"title":"AgCl (Ksp = 1.8 × 10⁻¹⁰) in 0.10 M NaCl","steps":[{"latex":"[\\text{Cl}^-] \\approx 0.10,\\ [\\text{Ag}^+] = s","explanation":""},{"latex":"s = \\tfrac{1.8\\times10^{-10}}{0.10} = 1.8\\times10^{-9}\\ \\text{M}","explanation":"About 7000 times less than in pure water."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_51acd917cdfc89', 'les_773f682a836d66', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Salting out soap in manufacturing, and gravimetric analysis, where excess reagent is added to precipitate an ion completely."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ffbf46bf5fe93', 'les_773f682a836d66', 1, 'practice', 'numeric', 3, 'Find the solubility of CaF₂ (Ksp = 3.9 × 10⁻¹¹) in 0.10 M NaF, in units of $10^{-9}$ M.', '{"answer":3.9,"tolerance":0.01}', '[]', '$s(0.10)^2 = 3.9\times10^{-11}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_083a8b7fdd4b21', 'les_773f682a836d66', 2, 'practice', 'multiple_choice', 2, 'Adding NaCl to a saturated AgCl solution causes…', '{"choices":["more AgCl to dissolve","AgCl to precipitate","no change","AgCl to melt"],"answer":1}', '[]', 'Q > Ksp.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_51acd917cdfc89', 'les_773f682a836d66', 3, 'practice', 'multiple_choice', 2, 'Adding sodium acetate to acetic acid makes the pH…', '{"choices":["fall","rise","stay the same","reach 7"],"answer":1}', '[]', 'Less ionization means less H⁺.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_acece0e0680e31', 'les_773f682a836d66', 4, 'review', 'multiple_choice', 3, 'The common-ion effect is an application of…', '{"choices":["Hess''s law","Le Châtelier''s principle","Charles''s law","the Pauli principle"],"answer":1}', '[]', 'A stress shifts the equilibrium.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_773f682a836d66', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_773f682a836d66', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: composition-mixtures
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9e9f7b8187f97c', 'composition-mixtures', 'Composition of mixtures', 'Use elemental analysis to find the composition and purity of mixtures, solving with mass percent and mole relationships.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_927146380b309f', 'les_9e9f7b8187f97c', 1, 'Distinguish pure substances (fixed composition) from mixtures (variable).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8359e12cdc9434', 'les_9e9f7b8187f97c', 2, 'Find percent purity from a measured product.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd6dbed492935e', 'les_9e9f7b8187f97c', 3, 'Solve for the composition of a two-component mixture from elemental analysis.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_927146380b309f', 'les_9e9f7b8187f97c', 'learn', 1, 'definition', '{"term":"Pure vs mixture","body":"A pure compound always has the same mass percent of each element (law of definite proportions). A mixture''s composition varies, so measuring one element''s mass tells you the proportions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8359e12cdc9434', 'les_9e9f7b8187f97c', 'learn', 2, 'worked_example', '{"title":"Heating a 2.00 g sample of impure limestone releases 0.86 g of CO₂ (CaCO₃ → CaO + CO₂). Find the percent CaCO₃","steps":[{"latex":"m_{\\text{CaCO}_3} = 0.86\\ \\text{g CO}_2\\times\\tfrac{100.09}{44.01} = 1.96\\ \\text{g}","explanation":"1 : 1 mole ratio."},{"latex":"\\tfrac{1.96}{2.00}\\times100\\% \\approx 98\\%","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd6dbed492935e', 'les_9e9f7b8187f97c', 'learn', 3, 'worked_example', '{"title":"A 10.00 g mixture of NaCl and KCl contains 5.50 g of chlorine. Find the mass of NaCl","steps":[{"latex":"x\\tfrac{35.45}{58.44} + (10.00 - x)\\tfrac{35.45}{74.55} = 5.50","explanation":"x = grams of NaCl."},{"latex":"x \\approx 5.68\\ \\text{g NaCl}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0b03f986547b31', 'les_9e9f7b8187f97c', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Assaying ores, checking drug purity, and food labs measuring protein from nitrogen content."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_927146380b309f', 'les_9e9f7b8187f97c', 1, 'practice', 'numeric', 2, 'A 5.00 g sample of impure NaCl gives 11.48 g of AgCl (143.32 g/mol). Find the percent NaCl, to the nearest percent.', '{"answer":94,"tolerance":1,"unit":"%"}', '[]', '$\frac{11.48}{143.32} = 0.0801$ mol; ×58.44 = 4.68 g; 93.6%.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8359e12cdc9434', 'les_9e9f7b8187f97c', 2, 'practice', 'multiple_choice', 2, 'Which always has the same composition by mass?', '{"choices":["air","brass","water","seawater"],"answer":2}', '[]', 'A pure compound.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd6dbed492935e', 'les_9e9f7b8187f97c', 3, 'practice', 'numeric', 3, 'A mixture of CaCO₃ and inert sand (5.00 g) loses 1.10 g as CO₂ when heated. Find the mass of CaCO₃, to two decimal places.', '{"answer":2.5,"tolerance":0.01,"unit":"g"}', '[]', '$1.10\times\frac{100.09}{44.01} = 2.50$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0b03f986547b31', 'les_9e9f7b8187f97c', 4, 'review', 'multiple_choice', 3, 'Elemental analysis of a mixture can find its composition because…', '{"choices":["each component has a fixed element percent","mixtures are compounds","mass isn''t conserved","elements change"],"answer":0}', '[]', 'The components'' fixed compositions set up equations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9e9f7b8187f97c', (SELECT id FROM concepts WHERE slug = 'the-mole'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9e9f7b8187f97c', (SELECT id FROM formulas WHERE slug = 'molar-mass-moles'), 1);

-- Lesson: concentration-over-time
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_727284c029f181', 'concentration-over-time', 'Concentration changes over time', 'Use integrated rate laws to find concentrations and times, identify reaction order from linear plots, and compare half-lives of different orders.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_99b91c11ac3120', 'les_727284c029f181', 1, 'Apply zero-, first- and second-order integrated rate laws.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0696f086ff606e', 'les_727284c029f181', 2, 'Identify order from which plot is linear: [A], ln[A] or 1/[A] against t.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e5122ff33bdae', 'les_727284c029f181', 3, 'Use half-life relationships, including the constant first-order half-life.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_99b91c11ac3120', 'les_727284c029f181', 'learn', 1, 'definition', '{"term":"Integrated laws","body":"Zero order: $[A] = [A]_0 - kt$ (a plot of [A] vs t is linear, slope −k). First order: $\\ln[A] = \\ln[A]_0 - kt$ (ln[A] vs t is linear). Second order: $\\frac1{[A]} = \\frac1{[A]_0} + kt$ (1/[A] vs t is linear, slope +k)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0696f086ff606e', 'les_727284c029f181', 'learn', 2, 'worked_example', '{"title":"First order, k = 0.10 s⁻¹, [A]₀ = 0.50 M","steps":[{"latex":"[A]_{10\\ \\text{s}} = 0.50e^{-1.0} \\approx 0.184\\ \\text{M}","explanation":""},{"latex":"t = \\tfrac{\\ln(0.50/0.10)}{0.10} \\approx 16.1\\ \\text{s}","explanation":"Time to reach 0.10 M."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e5122ff33bdae', 'les_727284c029f181', 'learn', 3, 'worked_example', '{"title":"Second order, k = 0.20 M⁻¹s⁻¹, [A]₀ = 0.50 M","steps":[{"latex":"t_{1/2} = \\tfrac{1}{k[A]_0} = \\tfrac{1}{0.20(0.50)} = 10\\ \\text{s}","explanation":"The next half-life is 20 s: second-order half-lives grow."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_068a075d8e2fb5', 'les_727284c029f181', 'experiment', 4, 'activity', '{"activity":"kinetics","title":"Watch each order decay","params":{"order":"1","k":0.1,"A0":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13801228f96c72', 'les_727284c029f181', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Radioactive dating and drug clearance are first order; the dimerization of some gases is second order."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_99b91c11ac3120', 'les_727284c029f181', 1, 'practice', 'numeric', 2, 'A first-order reaction has t½ = 25 s. What fraction remains after 100 s? Give a decimal.', '{"answer":0.0625,"tolerance":0.0001}', '[]', 'Four half-lives: $\left(\frac12\right)^4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0696f086ff606e', 'les_727284c029f181', 2, 'practice', 'numeric', 3, 'Zero order with k = 0.020 M/s and [A]₀ = 0.80 M. How long until A is used up?', '{"answer":40,"unit":"s"}', '[]', '$\frac{0.80}{0.020}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e5122ff33bdae', 'les_727284c029f181', 3, 'practice', 'multiple_choice', 2, 'A plot of 1/[A] against t is a straight line with positive slope. The reaction is…', '{"choices":["zero order","first order","second order","can''t tell"],"answer":2}', '[]', 'Integrated second-order law.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_068a075d8e2fb5', 'les_727284c029f181', 4, 'review', 'multiple_choice', 3, 'Which order has a half-life independent of starting concentration?', '{"choices":["zero","first","second","all"],"answer":1}', '[]', '$t_{1/2} = \frac{0.693}{k}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_727284c029f181', (SELECT id FROM concepts WHERE slug = 'kinetics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_727284c029f181', (SELECT id FROM formulas WHERE slug = 'rate-laws'), 1);

-- Lesson: daltons-law-gas-stoichiometry
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_75225566d4824b', 'daltons-law-gas-stoichiometry', 'Dalton''s law and gas stoichiometry', 'Use partial pressures and mole fractions, correct for water vapor when collecting gas over water, and combine PV = nRT with stoichiometry.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_800ffaf3a85328', 'les_75225566d4824b', 1, 'Use Dalton''s law, P_total = ΣP_i, and P_i = X_iP_total.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_48d4e19957d53c', 'les_75225566d4824b', 2, 'Correct for water vapor when a gas is collected over water.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5aede374296d86', 'les_75225566d4824b', 3, 'Find gas volumes from reaction stoichiometry with PV = nRT.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_800ffaf3a85328', 'les_75225566d4824b', 'learn', 1, 'definition', '{"term":"Partial pressures","body":"In a gas mixture each gas acts independently: $P_{total} = P_1 + P_2 + \\cdots$, and each partial pressure is $P_i = X_iP_{total}$, where $X_i = \\frac{n_i}{n_{total}}$ is the mole fraction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_48d4e19957d53c', 'les_75225566d4824b', 'learn', 2, 'definition', '{"term":"Collecting over water","body":"Gas bubbled into an inverted bottle of water is mixed with water vapor, so $P_{gas} = P_{total} - P_{\\text{H}_2\\text{O}}$. Water''s vapor pressure is 23.8 torr at 25 °C."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5aede374296d86', 'les_75225566d4824b', 'learn', 3, 'worked_example', '{"title":"Zn + 2HCl → ZnCl₂ + H₂: 2.00 g of Zn reacts; H₂ is collected over water at 25 °C and 745 torr total","steps":[{"latex":"n_{\\text{H}_2} = \\tfrac{2.00}{65.38} = 0.0306\\ \\text{mol}","explanation":"1 : 1 ratio."},{"latex":"P_{\\text{H}_2} = 745 - 23.8 = 721\\ \\text{torr} = 0.949\\ \\text{atm}","explanation":""},{"latex":"V = \\tfrac{nRT}{P} = \\tfrac{0.0306(0.08206)(298)}{0.949}","explanation":""},{"latex":"V \\approx 0.789\\ \\text{L}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc2e5f4908b0b1', 'les_75225566d4824b', 'experiment', 4, 'activity', '{"activity":"ideal-gas","title":"PV = nRT for the collected gas"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d435d1d261af7a', 'les_75225566d4824b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scuba divers track the partial pressure of O₂ (too high is toxic at depth); airbags are sized with gas stoichiometry."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_800ffaf3a85328', 'les_75225566d4824b', 1, 'practice', 'numeric', 2, 'A mixture has 2.0 mol N₂ and 0.50 mol O₂ at a total of 1.25 atm. Find P of O₂.', '{"answer":0.25,"unit":"atm"}', '[]', '$X = \frac{0.5}{2.5} = 0.20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_48d4e19957d53c', 'les_75225566d4824b', 2, 'practice', 'numeric', 3, 'What volume of CO₂ at 1.00 atm and 298 K forms when 10.0 g of CaCO₃ (100.09 g/mol) decomposes? Give two decimal places.', '{"answer":2.44,"tolerance":0.01,"unit":"L"}', '[]', '$0.0999$ mol $\times \frac{0.08206(298)}{1.00}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5aede374296d86', 'les_75225566d4824b', 3, 'practice', 'multiple_choice', 2, 'Adding helium to a rigid flask of N₂ changes the N₂ partial pressure by…', '{"choices":["raising it","lowering it","nothing","doubling it"],"answer":2}', '[]', 'Gases act independently.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc2e5f4908b0b1', 'les_75225566d4824b', 4, 'review', 'multiple_choice', 3, 'Why subtract water''s vapor pressure when collecting gas over water?', '{"choices":["water absorbs the gas","the bottle also contains water vapor","water is heavy","to correct for temperature"],"answer":1}', '[]', 'Dalton''s law.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_75225566d4824b', (SELECT id FROM concepts WHERE slug = 'gas-laws'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_75225566d4824b', (SELECT id FROM formulas WHERE slug = 'combined-gas-law'), 1);

-- Lesson: direction-reversible
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_09807a0bff00d9', 'direction-reversible', 'Direction of reversible reactions', 'Predict whether a reversible reaction proceeds forward or in reverse by comparing forward and reverse rates, and connect that to macroscopic observations.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5dac00358b8826', 'les_09807a0bff00d9', 1, 'Decide the net direction from which rate is larger.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f78312ba14ee0b', 'les_09807a0bff00d9', 2, 'Connect net direction to observable changes (color, pressure, pH).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_00cfc9de80fef0', 'les_09807a0bff00d9', 3, 'Explain that a reaction can be run from either side to the same equilibrium.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5dac00358b8826', 'les_09807a0bff00d9', 'learn', 1, 'definition', '{"term":"Net direction","body":"If the forward rate is larger, the net reaction goes forward: products accumulate. If the reverse rate is larger, it goes backward. At equilibrium the rates are equal and nothing changes macroscopically."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f78312ba14ee0b', 'les_09807a0bff00d9', 'learn', 2, 'worked_example', '{"title":"Start the N₂O₄ ⇌ 2NO₂ system with pure NO₂ instead","steps":[{"latex":"\\text{reverse rate} > \\text{forward rate initially}","explanation":"The brown color fades as N₂O₄ forms."},{"latex":"K\\ \\text{is unchanged}","explanation":"Same equilibrium ratio at the same temperature: either starting point works."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_00cfc9de80fef0', 'les_09807a0bff00d9', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rechargeable batteries are run forward to discharge and backward to recharge."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5dac00358b8826', 'les_09807a0bff00d9', 1, 'practice', 'multiple_choice', 2, 'Starting with only products, the net reaction initially goes…', '{"choices":["forward","in reverse","nowhere","it can''t happen"],"answer":1}', '[]', 'Only the reverse reaction can occur at first.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f78312ba14ee0b', 'les_09807a0bff00d9', 2, 'practice', 'multiple_choice', 2, 'A brown NO₂ sample slowly gets lighter in a sealed flask. The net reaction is…', '{"choices":["2NO₂ → N₂O₄","N₂O₄ → 2NO₂","at equilibrium","stopped"],"answer":0}', '[]', 'NO₂ is being consumed.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_00cfc9de80fef0', 'les_09807a0bff00d9', 3, 'practice', 'multiple_choice', 3, 'Starting from pure reactants versus pure products (same atoms and temperature), the equilibrium state is…', '{"choices":["different","the same","reached only from reactants","random"],"answer":1}', '[]', 'K is fixed at a given temperature.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a531b03156f5e1', 'les_09807a0bff00d9', 4, 'review', 'multiple_choice', 3, 'When the forward rate exceeds the reverse rate,…', '{"choices":["the system is at equilibrium","products are accumulating","reactants are accumulating","K changes"],"answer":1}', '[]', 'Net forward reaction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_09807a0bff00d9', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_09807a0bff00d9', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: elementary-reactions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_44605884f1dfa3', 'elementary-reactions', 'Elementary reactions and collision model', 'Write rate laws directly from elementary steps using molecularity, and use the collision model to explain orientation and energy requirements.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5ddbb31ec649b6', 'les_44605884f1dfa3', 1, 'Define elementary reactions and molecularity (uni-, bi-, termolecular).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ed5314d34fa5e0', 'les_44605884f1dfa3', 2, 'Write the rate law of an elementary step from its coefficients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e64ea1bfa20f14', 'les_44605884f1dfa3', 3, 'Explain the energy and orientation requirements of the collision model, including the fraction e^(−Eₐ/RT).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ddbb31ec649b6', 'les_44605884f1dfa3', 'learn', 1, 'definition', '{"term":"Elementary steps","body":"An elementary reaction happens in a single collision, exactly as written. Only for elementary steps does the rate law follow from the coefficients: A → products, rate = k[A]; A + B → products, rate = k[A][B]; 2A → products, rate = k[A]². Three-particle collisions are rare."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed5314d34fa5e0', 'les_44605884f1dfa3', 'learn', 2, 'definition', '{"term":"Collision model","body":"Particles must collide with enough energy (at least Eₐ) and the right orientation. The fraction with enough energy is about $e^{-E_a/RT}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e64ea1bfa20f14', 'les_44605884f1dfa3', 'learn', 3, 'worked_example', '{"title":"Eₐ = 50 kJ/mol: fraction of collisions with enough energy","steps":[{"latex":"298\\ \\text{K}: e^{-50{,}000/(8.314\\cdot 298)} \\approx 1.7\\times10^{-9}","explanation":""},{"latex":"308\\ \\text{K}: \\approx 3.3\\times10^{-9}","explanation":"A 10 K rise nearly doubles it."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90b03ffe0a18dd', 'les_44605884f1dfa3', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Atmospheric chemists model ozone with dozens of elementary steps; enzyme active sites work partly by holding reactants in the right orientation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5ddbb31ec649b6', 'les_44605884f1dfa3', 1, 'practice', 'multiple_choice', 2, 'What is the rate law for the elementary step NO + O₃ → NO₂ + O₂?', '{"choices":["k[NO]","k[NO][O₃]","k[NO]²[O₃]","k[NO₂][O₂]"],"answer":1}', '[]', 'Bimolecular.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ed5314d34fa5e0', 'les_44605884f1dfa3', 2, 'practice', 'multiple_choice', 2, 'Why can''t you write an overall reaction''s rate law from its coefficients?', '{"choices":["coefficients are wrong","the overall reaction may involve several steps","rates are constant","it''s always first order"],"answer":1}', '[]', 'Only elementary steps work that way.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e64ea1bfa20f14', 'les_44605884f1dfa3', 3, 'practice', 'numeric', 3, 'What fraction of collisions exceed Eₐ = 75 kJ/mol at 298 K? Give it in units of $10^{-14}$, to one decimal place.', '{"answer":7.1,"tolerance":0.1}', '[]', '$e^{-75{,}000/(8.314\cdot298)} \approx 7.1\times10^{-14}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90b03ffe0a18dd', 'les_44605884f1dfa3', 4, 'review', 'multiple_choice', 3, 'A collision with enough energy but the wrong orientation…', '{"choices":["always reacts","doesn''t react","reacts slowly","reverses"],"answer":1}', '[]', 'Both requirements must be met.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_44605884f1dfa3', (SELECT id FROM concepts WHERE slug = 'kinetics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_44605884f1dfa3', (SELECT id FROM formulas WHERE slug = 'rate-laws'), 1);

-- Lesson: energy-diagrams
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9f52a5837a1805', 'energy-diagrams', 'Energy diagrams', 'Represent endothermic and exothermic reactions with energy diagrams, read ΔH from them, and connect them to bonds broken and formed.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_940d70ca5328d7', 'les_9f52a5837a1805', 1, 'Draw and read energy diagrams for exothermic and endothermic reactions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2451db2a6ae7a7', 'les_9f52a5837a1805', 2, 'Read ΔH as products'' energy minus reactants'' energy.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dfa2c931b87725', 'les_9f52a5837a1805', 3, 'Relate the diagram to energy absorbed breaking bonds and released forming them.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_940d70ca5328d7', 'les_9f52a5837a1805', 'learn', 1, 'definition', '{"term":"Reading the diagram","body":"Energy is on the vertical axis. If the products sit lower, energy was released: exothermic, ΔH < 0. If higher, energy was absorbed: endothermic, ΔH > 0. Breaking bonds always takes energy; forming bonds always releases it. The balance sets the sign of ΔH."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2451db2a6ae7a7', 'les_9f52a5837a1805', 'learn', 2, 'worked_example', '{"title":"Reactants at 200 kJ, products at 50 kJ, peak at 250 kJ","steps":[{"latex":"\\Delta H = 50 - 200 = -150\\ \\text{kJ}","explanation":"Exothermic."},{"latex":"E_a = 250 - 200 = 50\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dfa2c931b87725', 'les_9f52a5837a1805', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Hand warmers (exothermic iron oxidation), cold packs (endothermic dissolving) and photosynthesis (endothermic, driven by light)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_940d70ca5328d7', 'les_9f52a5837a1805', 1, 'practice', 'numeric', 2, 'Reactants at 80 kJ, products at 130 kJ. Find ΔH.', '{"answer":50,"unit":"kJ"}', '[]', 'Endothermic.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2451db2a6ae7a7', 'les_9f52a5837a1805', 2, 'practice', 'multiple_choice', 2, 'In an exothermic reaction,…', '{"choices":["bonds formed release more energy than bonds broken absorb","no bonds break","products have more energy","ΔH > 0"],"answer":0}', '[]', 'Net release.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dfa2c931b87725', 'les_9f52a5837a1805', 3, 'practice', 'multiple_choice', 2, 'Breaking a chemical bond…', '{"choices":["releases energy","requires energy","has no energy change","depends on the bond"],"answer":1}', '[]', 'Always endothermic.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bcb7e7efa0ddc1', 'les_9f52a5837a1805', 4, 'review', 'multiple_choice', 3, 'A catalyst changes which feature of an energy diagram?', '{"choices":["the reactants'' level","the products'' level","the height of the peak","ΔH"],"answer":2}', '[]', 'Lower Eₐ.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9f52a5837a1805', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9f52a5837a1805', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: enthalpy-of-formation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4b3a57ad2617f6', 'enthalpy-of-formation', 'Enthalpy of formation', 'Write formation reactions from standard-state elements, and compute ΔH°_rxn from tables of standard enthalpies of formation.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fce59d9912cb37', 'les_4b3a57ad2617f6', 1, 'Write the formation reaction of a compound (1 mol product from standard-state elements).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_977ca2c278c660', 'les_4b3a57ad2617f6', 2, 'Recognize that ΔH°_f is zero for elements in their standard states.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_19af680d40d6a9', 'les_4b3a57ad2617f6', 3, 'Use ΔH°_rxn = ΣnΔH°_f(products) − ΣnΔH°_f(reactants).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fce59d9912cb37', 'les_4b3a57ad2617f6', 'learn', 1, 'definition', '{"term":"Formation reactions","body":"ΔH°_f forms exactly 1 mol of a compound from its elements in their standard states (25 °C, 1 atm): for ammonia, $\\frac12\\text{N}_2(g) + \\frac32\\text{H}_2(g) \\to \\text{NH}_3(g)$, ΔH°_f = −46.1 kJ/mol. Fractions are allowed in formation equations."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_977ca2c278c660', 'les_4b3a57ad2617f6', 'learn', 2, 'worked_example', '{"title":"Combustion of ethanol: C₂H₅OH(l) + 3O₂ → 2CO₂ + 3H₂O(l) (ΔH°_f: C₂H₅OH −277.7, CO₂ −393.5, H₂O(l) −285.8 kJ/mol)","steps":[{"latex":"\\textstyle\\sum_{prod} = 2(-393.5) + 3(-285.8) = -1644.4","explanation":"Products."},{"latex":"\\Delta H^\\circ = -1644.4 - (-277.7)","explanation":"O₂ is zero."},{"latex":"\\Delta H^\\circ = -1366.7\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19af680d40d6a9', 'les_4b3a57ad2617f6', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every thermodynamic table in engineering and the energy content of biofuels are computed this way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fce59d9912cb37', 'les_4b3a57ad2617f6', 1, 'practice', 'numeric', 2, 'Find ΔH° for CaCO₃(s) → CaO(s) + CO₂(g) (ΔH°_f: CaCO₃ −1207, CaO −635, CO₂ −393.5 kJ/mol), to one decimal place.', '{"answer":178.5,"tolerance":0.1,"unit":"kJ"}', '[]', '$-635 - 393.5 + 1207$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_977ca2c278c660', 'les_4b3a57ad2617f6', 2, 'practice', 'multiple_choice', 2, 'Which equation represents the standard formation of water?', '{"choices":["2H₂ + O₂ → 2H₂O(l)","H₂(g) + ½O₂(g) → H₂O(l)","H₂O(l) → H₂ + ½O₂","2H + O → H₂O"],"answer":1}', '[]', 'One mole of product from standard-state elements.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19af680d40d6a9', 'les_4b3a57ad2617f6', 3, 'practice', 'multiple_choice', 2, 'ΔH°_f of Br₂(l) is…', '{"choices":["0","positive","negative","undefined"],"answer":0}', '[]', 'Bromine is a liquid at standard conditions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c26abda70416a0', 'les_4b3a57ad2617f6', 4, 'review', 'multiple_choice', 3, 'Why is ΔH°_f of Br₂(g) not zero?', '{"choices":["it''s an element","gas is not bromine''s standard state","it''s unstable","it''s a compound"],"answer":1}', '[]', 'It includes vaporization.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4b3a57ad2617f6', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4b3a57ad2617f6', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: enthalpy-of-reaction
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_50c465e95a420e', 'enthalpy-of-reaction', 'Introduction to enthalpy of reaction', 'Interpret ΔH_rxn per mole of reaction as written, and use stoichiometry to find the heat released or absorbed by a given amount of reactant.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4704f43198b148', 'les_50c465e95a420e', 1, 'Read ΔH as the heat per mole of reaction as written.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69814ca9333444', 'les_50c465e95a420e', 2, 'Convert grams of a reactant into heat using the coefficients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5d8ba85480b983', 'les_50c465e95a420e', 3, 'Find ΔH from a measured heat and the amount reacted.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4704f43198b148', 'les_50c465e95a420e', 'learn', 1, 'definition', '{"term":"Per mole of reaction","body":"In $2\\text{H}_2 + \\text{O}_2 \\to 2\\text{H}_2\\text{O}$, ΔH = −572 kJ means 572 kJ is released when 2 mol of H₂ react with 1 mol of O₂. That''s −286 kJ per mole of H₂."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69814ca9333444', 'les_50c465e95a420e', 'learn', 2, 'worked_example', '{"title":"Heat released when 10.0 g of H₂ burns","steps":[{"latex":"n = \\tfrac{10.0}{2.016} = 4.96\\ \\text{mol H}_2","explanation":""},{"latex":"q = 4.96\\ \\text{mol}\\times\\tfrac{-572\\ \\text{kJ}}{2\\ \\text{mol H}_2} \\approx -1420\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d8ba85480b983', 'les_50c465e95a420e', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rocket designers choose fuels by heat per kilogram; hydrogen releases about 142 kJ per gram, three times as much as gasoline."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4704f43198b148', 'les_50c465e95a420e', 1, 'practice', 'numeric', 2, 'CH₄ + 2O₂ → CO₂ + 2H₂O, ΔH = −890 kJ. How much heat comes from 8.02 g of CH₄ (16.04 g/mol)?', '{"answer":-445,"unit":"kJ"}', '[]', '0.500 mol × −890.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69814ca9333444', 'les_50c465e95a420e', 2, 'practice', 'numeric', 3, 'N₂ + 3H₂ → 2NH₃, ΔH = −92 kJ. How much heat is released forming 34.0 g of NH₃ (17.03 g/mol)?', '{"answer":92,"tolerance":0.5,"unit":"kJ"}', '[]', '2.00 mol NH₃ is one mole of reaction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d8ba85480b983', 'les_50c465e95a420e', 3, 'practice', 'multiple_choice', 2, 'ΔH = +180 kJ for N₂ + O₂ → 2NO. Forming 4 mol of NO requires…', '{"choices":["180 kJ","360 kJ","90 kJ","720 kJ"],"answer":1}', '[]', 'Twice the reaction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_89474357024091', 'les_50c465e95a420e', 4, 'review', 'multiple_choice', 3, 'If an equation is multiplied by 3, ΔH…', '{"choices":["stays the same","triples","changes sign","is divided by 3"],"answer":1}', '[]', 'Enthalpy is extensive.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_50c465e95a420e', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_50c465e95a420e', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: formal-charge
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ada10ebec63b53', 'formal-charge', 'Resonance and formal charge', 'Compute formal charges to choose the best Lewis structure, draw resonance structures, and recognize expanded octets.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_34a4142c5cdfc3', 'les_ada10ebec63b53', 1, 'Compute formal charge: FC = valence − nonbonding electrons − ½ bonding electrons.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_70333e33c05a5b', 'les_ada10ebec63b53', 2, 'Choose the Lewis structure with formal charges closest to zero, negative charges on the more electronegative atoms.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10197705c34a60', 'les_ada10ebec63b53', 3, 'Draw resonance structures and recognize expanded octets in period-3 and later elements.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34a4142c5cdfc3', 'les_ada10ebec63b53', 'learn', 1, 'definition', '{"term":"Formal charge","body":"$FC = V - N - \\frac{B}{2}$, where V is the number of valence electrons, N the nonbonding electrons on the atom, and B the bonding electrons around it. The formal charges add up to the ion''s charge. The best structure has formal charges as close to zero as possible, with any negative charge on the more electronegative atom."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_70333e33c05a5b', 'les_ada10ebec63b53', 'learn', 2, 'worked_example', '{"title":"Two structures for CO₂: O=C=O versus O≡C–O","steps":[{"latex":"\\text{O=C=O}:\\ 0,\\ 0,\\ 0","explanation":"Preferred."},{"latex":"\\text{O≡C–O}:\\ +1,\\ 0,\\ -1","explanation":"Charges separated: worse."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10197705c34a60', 'les_ada10ebec63b53', 'learn', 3, 'definition', '{"term":"Expanded octets","body":"Atoms in period 3 or below (P, S, Cl, Xe) can hold more than 8 electrons: SF₆ has 12 around S, PCl₅ has 10. Sometimes that lowers formal charges, as in the sulfate ion."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d65069aa0f8e21', 'les_ada10ebec63b53', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Formal charge predicts reactive sites, such as which atom of the thiocyanate ion (SCN⁻) bonds to metal ions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34a4142c5cdfc3', 'les_ada10ebec63b53', 1, 'practice', 'numeric', 2, 'Find the formal charge on N in NH₄⁺.', '{"answer":1}', '[]', '$5 - 0 - \frac82$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_70333e33c05a5b', 'les_ada10ebec63b53', 2, 'practice', 'numeric', 2, 'Find the formal charge on the single-bonded O (three lone pairs) in NO₃⁻.', '{"answer":-1}', '[]', '$6 - 6 - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10197705c34a60', 'les_ada10ebec63b53', 3, 'practice', 'multiple_choice', 2, 'Which atom can have an expanded octet?', '{"choices":["C","N","O","S"],"answer":3}', '[]', 'Period 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d65069aa0f8e21', 'les_ada10ebec63b53', 4, 'review', 'multiple_choice', 3, 'In the best Lewis structure, negative formal charge should be on…', '{"choices":["the least electronegative atom","the most electronegative atom","the central atom","hydrogen"],"answer":1}', '[]', 'It can best hold extra electron density.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ada10ebec63b53', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: free-energy-dissolution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d7bdc6395f1f9b', 'free-energy-dissolution', 'Free energy of dissolution', 'Explain dissolving with enthalpy (breaking and forming interactions) and entropy, and use ΔG = ΔH − TΔS to see why even endothermic dissolving can be favorable.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_de7e390765135b', 'les_d7bdc6395f1f9b', 1, 'Break dissolving into separating the solute, separating the solvent and solvation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_131541cbd0343c', 'les_d7bdc6395f1f9b', 2, 'Explain the role of entropy in dissolving.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1af8dd56f0c065', 'les_d7bdc6395f1f9b', 3, 'Use ΔG = ΔH − TΔS to judge whether dissolving is favorable.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de7e390765135b', 'les_d7bdc6395f1f9b', 'learn', 1, 'definition', '{"term":"Energy steps","body":"Dissolving takes energy to break solute–solute and solvent–solvent interactions, and releases energy as solute–solvent interactions form. If more is released, dissolving is exothermic; if less, endothermic, and the solution cools."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_131541cbd0343c', 'les_d7bdc6395f1f9b', 'learn', 2, 'definition', '{"term":"Entropy","body":"Dispersing ions or molecules through a solvent usually increases entropy (ΔS > 0). That''s why some salts dissolve even though it costs energy: $\\Delta G = \\Delta H - T\\Delta S < 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1af8dd56f0c065', 'les_d7bdc6395f1f9b', 'learn', 3, 'worked_example', '{"title":"NH₄NO₃ dissolving: ΔH = +25.7 kJ/mol, ΔS = +108.7 J/(mol·K), at 298 K","steps":[{"latex":"\\Delta G = 25.7 - 298(0.1087)","explanation":"Convert ΔS to kJ."},{"latex":"\\Delta G \\approx -6.7\\ \\text{kJ/mol}","explanation":"Favorable, though endothermic: entropy wins."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_88fe7f48d1f74a', 'les_d7bdc6395f1f9b', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Instant cold packs, and why some gases (with negative ΔS of dissolving) become less soluble as temperature rises."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de7e390765135b', 'les_d7bdc6395f1f9b', 1, 'practice', 'numeric', 2, 'A salt dissolves with ΔH = +15 kJ/mol and ΔS = +40 J/(mol·K). Find ΔG at 298 K, to one decimal place.', '{"answer":3.1,"tolerance":0.1,"unit":"kJ/mol"}', '[]', '$15 - 298(0.040) = 3.08$: not favorable.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_131541cbd0343c', 'les_d7bdc6395f1f9b', 2, 'practice', 'numeric', 3, 'Above what temperature does that salt dissolve favorably?', '{"answer":375,"unit":"K"}', '[]', '$T = \frac{\Delta H}{\Delta S} = \frac{15{,}000}{40}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1af8dd56f0c065', 'les_d7bdc6395f1f9b', 3, 'practice', 'multiple_choice', 2, 'A cold pack gets cold because dissolving NH₄NO₃ is…', '{"choices":["exothermic","endothermic","a phase change","a combustion"],"answer":1}', '[]', 'It absorbs heat from its surroundings.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_88fe7f48d1f74a', 'les_d7bdc6395f1f9b', 4, 'review', 'multiple_choice', 3, 'Endothermic dissolving can still be spontaneous because…', '{"choices":["ΔH is negative","the entropy increase outweighs the enthalpy cost","K is zero","temperature is irrelevant"],"answer":1}', '[]', '$-T\Delta S$ dominates.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d7bdc6395f1f9b', (SELECT id FROM concepts WHERE slug = 'solutions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d7bdc6395f1f9b', (SELECT id FROM formulas WHERE slug = 'free-energy'), 1);

-- Lesson: galvanic-cells
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4eb5fc89396c88', 'galvanic-cells', 'Galvanic cells', 'Describe how galvanic cells turn redox reactions into electric current, write cell notation, and compute standard cell potentials and ΔG°.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_696b1f11f15797', 'les_4eb5fc89396c88', 1, 'Identify the anode, cathode, electron flow and the salt bridge''s role.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_054467d3781ef2', 'les_4eb5fc89396c88', 2, 'Write cell notation, anode | anode ion || cathode ion | cathode.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7330d4f8984e31', 'les_4eb5fc89396c88', 3, 'Compute E°cell = E°cathode − E°anode and ΔG° = −nFE°.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_696b1f11f15797', 'les_4eb5fc89396c88', 'learn', 1, 'definition', '{"term":"Parts of a cell","body":"Oxidation happens at the anode, reduction at the cathode (\"an ox, red cat\"). Electrons flow through the wire from anode to cathode; the salt bridge lets ions move to keep both solutions neutral. In a galvanic cell the anode is negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_054467d3781ef2', 'les_4eb5fc89396c88', 'learn', 2, 'definition', '{"term":"Standard potentials","body":"Each half-reaction has a standard reduction potential E°. The more positive one is reduced (cathode). $E^\\circ_{cell} = E^\\circ_{cathode} - E^\\circ_{anode}$; don''t multiply E° by coefficients. A positive E°cell means a spontaneous reaction: $\\Delta G^\\circ = -nFE^\\circ < 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7330d4f8984e31', 'les_4eb5fc89396c88', 'learn', 3, 'worked_example', '{"title":"Zn | Zn²⁺ || Cu²⁺ | Cu (E°: Cu²⁺ +0.34 V, Zn²⁺ −0.76 V)","steps":[{"latex":"E^\\circ = 0.34 - (-0.76) = 1.10\\ \\text{V}","explanation":""},{"latex":"\\Delta G^\\circ = -2(96{,}485)(1.10) \\approx -212\\ \\text{kJ}","explanation":"n = 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa2e0a52322e86', 'les_4eb5fc89396c88', 'experiment', 4, 'activity', '{"activity":"galvanic-cell","title":"Build a cell","params":{"left":"Zn","right":"Cu","leftConc":1,"rightConc":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4539d28eebeeae', 'les_4eb5fc89396c88', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Swap in silver for copper and predict E° before reading it. Then drop [Zn²⁺] to 0.01 M: the voltage rises a little (the Nernst equation)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9838d02bd6a86', 'les_4eb5fc89396c88', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every battery, from AA cells to lithium-ion, and corrosion protection with sacrificial zinc on ship hulls."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_696b1f11f15797', 'les_4eb5fc89396c88', 1, 'practice', 'numeric', 2, 'Find E° for a Cu | Cu²⁺ || Ag⁺ | Ag cell (Ag⁺ +0.80 V).', '{"answer":0.46,"unit":"V"}', '[]', '$0.80 - 0.34$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_054467d3781ef2', 'les_4eb5fc89396c88', 2, 'practice', 'numeric', 3, 'Find ΔG° for that cell (n = 2), in kJ, to the nearest kJ.', '{"answer":-89,"tolerance":1,"unit":"kJ"}', '[]', '$-2(96{,}485)(0.46)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7330d4f8984e31', 'les_4eb5fc89396c88', 3, 'practice', 'multiple_choice', 2, 'In a galvanic cell, electrons flow…', '{"choices":["cathode to anode","anode to cathode through the wire","through the salt bridge","both ways"],"answer":1}', '[]', 'From where oxidation releases them.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa2e0a52322e86', 'les_4eb5fc89396c88', 4, 'review', 'multiple_choice', 3, 'The salt bridge is needed because…', '{"choices":["it carries electrons","it keeps the solutions electrically neutral","it raises the voltage","it stores charge"],"answer":1}', '[]', 'Ions move to balance charge buildup.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_15e1fc516df8df', 'subj_chem', 'electrochemistry', 'Electrochemistry', 'Redox reactions and the cells that convert chemical and electrical energy.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4eb5fc89396c88', (SELECT id FROM concepts WHERE slug = 'electrochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4eb5fc89396c88', (SELECT id FROM formulas WHERE slug = 'electrochemistry'), 1);

-- Lesson: hess-law-formation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9f2cb0f77ac5f4', 'hess-law-formation', 'Hess''s law and enthalpies of formation', 'Combine thermochemical equations with Hess''s law, and compute reaction enthalpies from standard enthalpies of formation.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6ee3b08c755025', 'les_9f2cb0f77ac5f4', 1, 'Manipulate thermochemical equations: reverse (flip sign) and scale (multiply ΔH).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f98b67f305557', 'les_9f2cb0f77ac5f4', 2, 'Add steps to reach a target reaction (Hess''s law).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2d7e4305f0b14b', 'les_9f2cb0f77ac5f4', 3, 'Use ΔH°_rxn = ΣnΔH°_f(products) − ΣnΔH°_f(reactants).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ee3b08c755025', 'les_9f2cb0f77ac5f4', 'learn', 1, 'definition', '{"term":"Hess''s law","body":"Enthalpy is a state function, so ΔH depends only on the start and end, not the path. Reverse a reaction: flip the sign of ΔH. Multiply a reaction: multiply ΔH."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f98b67f305557', 'les_9f2cb0f77ac5f4', 'learn', 2, 'worked_example', '{"title":"Find ΔH for C(s) + ½O₂ → CO(g)","steps":[{"latex":"\\text{C} + \\text{O}_2 \\to \\text{CO}_2\\quad \\Delta H = -393.5","explanation":""},{"latex":"\\text{CO}_2 \\to \\text{CO} + \\tfrac12\\text{O}_2\\quad \\Delta H = +283.0","explanation":"The CO combustion, reversed."},{"latex":"\\Delta H = -393.5 + 283.0 = -110.5\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d7e4305f0b14b', 'les_9f2cb0f77ac5f4', 'learn', 3, 'definition', '{"term":"Formation enthalpies","body":"ΔH°_f is the enthalpy change to form 1 mol of a compound from its elements in standard states. It''s zero for elements in standard state (O₂, C graphite). Then $\\Delta H^\\circ_{rxn} = \\sum n\\Delta H^\\circ_f(\\text{products}) - \\sum n\\Delta H^\\circ_f(\\text{reactants})$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_67c2a2706f5be8', 'les_9f2cb0f77ac5f4', 'learn', 4, 'worked_example', '{"title":"CH₄ + 2O₂ → CO₂ + 2H₂O(l), with ΔH°_f: CH₄ −74.8, CO₂ −393.5, H₂O(l) −285.8 kJ/mol","steps":[{"latex":"\\textstyle\\sum_{prod} = -393.5 + 2(-285.8) = -965.1","explanation":"Products."},{"latex":"\\Delta H^\\circ = -965.1 - (-74.8)","explanation":"O₂ is zero."},{"latex":"\\Delta H^\\circ = -890.3\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fa0f85821ceff', 'les_9f2cb0f77ac5f4', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Fuel energy ratings, rocket propellant design, and diet calories are all computed from formation-enthalpy tables."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ee3b08c755025', 'les_9f2cb0f77ac5f4', 1, 'practice', 'numeric', 2, 'Find ΔH° for 2CO + O₂ → 2CO₂ using ΔH°_f(CO) = −110.5 and ΔH°_f(CO₂) = −393.5 kJ/mol.', '{"answer":-566,"unit":"kJ"}', '[]', '$2(-393.5) - 2(-110.5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f98b67f305557', 'les_9f2cb0f77ac5f4', 2, 'practice', 'numeric', 3, 'Find ΔH° for C₂H₄ + H₂ → C₂H₆ (ΔH°_f: C₂H₄ +52.3, C₂H₆ −84.7 kJ/mol).', '{"answer":-137,"unit":"kJ"}', '[]', '$-84.7 - 52.3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2d7e4305f0b14b', 'les_9f2cb0f77ac5f4', 3, 'practice', 'multiple_choice', 2, 'ΔH°_f of O₂(g) is…', '{"choices":["−249 kJ/mol","0","+498 kJ/mol","undefined"],"answer":1}', '[]', 'An element in its standard state.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_67c2a2706f5be8', 'les_9f2cb0f77ac5f4', 4, 'review', 'multiple_choice', 3, 'Hess''s law works because enthalpy is…', '{"choices":["always negative","a state function","path-dependent","measured in joules"],"answer":1}', '[]', 'Only start and end states matter.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9f2cb0f77ac5f4', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9f2cb0f77ac5f4', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: hybridization-resonance
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d6f3818d3ec99e', 'hybridization-resonance', 'Hybridization and resonance', 'Assign sp, sp² and sp³ hybridization from electron domains, distinguish σ and π bonds, and describe molecules with resonance structures and fractional bond orders.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_75427dfe0d8eb8', 'les_d6f3818d3ec99e', 1, 'Assign hybridization from the number of electron domains.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a16c77230396bf', 'les_d6f3818d3ec99e', 2, 'Count σ and π bonds in single, double and triple bonds.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b7fc16e0f4c029', 'les_d6f3818d3ec99e', 3, 'Draw resonance structures and compute average bond orders.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_75427dfe0d8eb8', 'les_d6f3818d3ec99e', 'learn', 1, 'definition', '{"term":"Hybrid orbitals","body":"Atomic orbitals mix into equivalent hybrids pointing toward the electron domains: 2 domains give sp (180°), 3 give sp² (120°), 4 give sp³ (109.5°). Every single bond is one σ bond; a double bond is σ + π; a triple bond is σ + 2π. π bonds use unhybridized p orbitals."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a16c77230396bf', 'les_d6f3818d3ec99e', 'learn', 2, 'worked_example', '{"title":"Ethylene, H₂C=CH₂","steps":[{"latex":"\\text{each C: 3 domains} \\Rightarrow sp^2","explanation":"Planar, 120°."},{"latex":"5\\ \\sigma + 1\\ \\pi","explanation":"4 C–H σ bonds, plus the C=C σ and π."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b7fc16e0f4c029', 'les_d6f3818d3ec99e', 'learn', 3, 'definition', '{"term":"Resonance","body":"When one Lewis structure can''t place the electrons, the real molecule is an average (hybrid) of several. In NO₃⁻, the double bond can be drawn to any of three oxygens, so each N–O bond has order $\\frac{4}{3}$, between single and double, and all three are identical."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df099a59dad1ca', 'les_d6f3818d3ec99e', 'learn', 4, 'worked_example', '{"title":"Bond order in ozone, O₃","steps":[{"latex":"\\text{two structures: O=O–O and O–O=O}","explanation":""},{"latex":"\\text{bond order} = \\tfrac{1 + 2}{2} = 1.5","explanation":"Both O–O bonds are equal in length."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3a6039c5b4dc0', 'les_d6f3818d3ec99e', 'experiment', 5, 'activity', '{"activity":"vsepr","title":"Domains set the hybridization","params":{"domains":3,"lonePairs":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_45f315cea8d3d3', 'les_d6f3818d3ec99e', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Benzene''s resonance (bond order 1.5) makes it unusually stable; the rigid π bonds in retinal flip with light, which is how your eyes detect it."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_75427dfe0d8eb8', 'les_d6f3818d3ec99e', 1, 'practice', 'numeric', 2, 'How many π bonds are in CO₂?', '{"answer":2}', '[]', 'Two C=O double bonds.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a16c77230396bf', 'les_d6f3818d3ec99e', 2, 'practice', 'multiple_choice', 2, 'What is the hybridization of N in NH₃?', '{"choices":["sp","sp²","sp³","sp³d"],"answer":2}', '[]', '4 domains (3 bonds + 1 lone pair).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b7fc16e0f4c029', 'les_d6f3818d3ec99e', 3, 'practice', 'numeric', 3, 'Find the C–O bond order in carbonate, CO₃²⁻ (3 resonance structures). Give two decimal places.', '{"answer":1.33,"tolerance":0.01}', '[]', '4 bonding pairs over 3 bonds.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_df099a59dad1ca', 'les_d6f3818d3ec99e', 4, 'review', 'multiple_choice', 3, 'In resonance, the molecule…', '{"choices":["flips between structures","is a single average of the structures","exists as a mixture of molecules","has unequal bonds"],"answer":1}', '[]', 'The structures are representations, not different molecules.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d6f3818d3ec99e', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: ice-tables
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e99fa3c191f6d2', 'ice-tables', 'Equilibrium constants and ICE tables', 'Organize equilibrium problems with ICE tables, solve for equilibrium concentrations (exactly or with the small-x approximation), and calculate K from data.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3032421811183e', 'les_e99fa3c191f6d2', 1, 'Set up Initial, Change and Equilibrium rows using stoichiometry.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_045c6ea794035a', 'les_e99fa3c191f6d2', 2, 'Solve for x exactly, or with the small-x approximation when it''s valid (the 5% rule).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2407bb3ad194d1', 'les_e99fa3c191f6d2', 3, 'Calculate K from equilibrium data, and Kp from Kc.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3032421811183e', 'les_e99fa3c191f6d2', 'learn', 1, 'definition', '{"term":"ICE tables","body":"Write Initial concentrations, the Change in terms of x using the coefficients, and Equilibrium = initial + change. Substitute into K and solve for x."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_045c6ea794035a', 'les_e99fa3c191f6d2', 'learn', 2, 'worked_example', '{"title":"H₂ + I₂ ⇌ 2HI, K = 49, starting with 0.50 M H₂ and I₂","steps":[{"latex":"\\text{E: } [\\text{H}_2] = [\\text{I}_2] = 0.50 - x,\\ [\\text{HI}] = 2x","explanation":""},{"latex":"\\tfrac{(2x)^2}{(0.50 - x)^2} = 49 \\Rightarrow \\tfrac{2x}{0.50 - x} = 7","explanation":"A perfect square: take the square root."},{"latex":"x = 0.389 \\Rightarrow [\\text{HI}] = 0.778\\ \\text{M}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2407bb3ad194d1', 'les_e99fa3c191f6d2', 'learn', 3, 'definition', '{"term":"Small-x approximation","body":"When K is small, x may be negligible next to the initial concentration. Check afterward: if x is under 5% of the initial value, the shortcut is fine; otherwise solve the quadratic."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_31a14edbf00c04', 'les_e99fa3c191f6d2', 'learn', 4, 'worked_example', '{"title":"N₂O₄ ⇌ 2NO₂, K = 0.0080, starting with 0.20 M N₂O₄","steps":[{"latex":"\\tfrac{(2x)^2}{0.20 - x} = 0.0080","explanation":""},{"latex":"\\text{shortcut: } 4x^2 \\approx 0.0016 \\Rightarrow x \\approx 0.020","explanation":"That''s 10% of 0.20: too big."},{"latex":"\\text{quadratic: } x = 0.0190 \\Rightarrow [\\text{NO}_2] = 0.038\\ \\text{M}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81988d496d3304', 'les_e99fa3c191f6d2', 'experiment', 5, 'activity', '{"activity":"equilibrium","title":"Exact equilibrium for A + B ⇌ C","params":{"K":4,"A0":1,"B0":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f400e1436df619', 'les_e99fa3c191f6d2', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Industrial chemists use ICE tables to predict yields, and the same method underlies every weak-acid and solubility calculation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3032421811183e', 'les_e99fa3c191f6d2', 1, 'practice', 'numeric', 2, 'For A ⇌ B, K = 3. Starting with 1.00 M A and no B, find [B] at equilibrium.', '{"answer":0.75,"unit":"M"}', '[]', '$\frac{x}{1 - x} = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_045c6ea794035a', 'les_e99fa3c191f6d2', 2, 'practice', 'numeric', 3, 'For 2SO₂ + O₂ ⇌ 2SO₃, at equilibrium [SO₂] = 0.10, [O₂] = 0.050 and [SO₃] = 0.40 M. Find K.', '{"answer":320}', '[]', '$\frac{0.16}{0.01(0.050)}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2407bb3ad194d1', 'les_e99fa3c191f6d2', 3, 'practice', 'multiple_choice', 2, 'The small-x approximation is safe when…', '{"choices":["K is large","x is under 5% of the initial concentration","x is negative","always"],"answer":1}', '[]', 'Check after solving.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_31a14edbf00c04', 'les_e99fa3c191f6d2', 4, 'review', 'multiple_choice', 3, 'In an ICE table, the change row uses…', '{"choices":["equilibrium concentrations","coefficients times x","K","rates"],"answer":1}', '[]', 'Stoichiometry sets the ratio of changes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e99fa3c191f6d2', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e99fa3c191f6d2', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: intro-equilibrium
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2c77e5eecc318a', 'intro-equilibrium', 'Introduction to equilibrium', 'Describe reversible reactions reaching dynamic equilibrium, read concentration–time and rate–time graphs, and recognize that equilibrium doesn''t mean equal concentrations.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42f04768e363d0', 'les_2c77e5eecc318a', 1, 'Explain dynamic equilibrium: forward and reverse rates equal, concentrations constant.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a8db1bfdf59bc', 'les_2c77e5eecc318a', 2, 'Interpret concentration–time and rate–time graphs approaching equilibrium.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bf450461b09fcb', 'les_2c77e5eecc318a', 3, 'Explain why equilibrium concentrations are generally not equal.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42f04768e363d0', 'les_2c77e5eecc318a', 'learn', 1, 'definition', '{"term":"Reversible reactions","body":"In a closed container, products can react back. At first the forward rate is high and the reverse rate zero; as products build up, the reverse rate rises and the forward rate falls until they''re equal. From then on concentrations stay constant, though both reactions continue: equilibrium is dynamic."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a8db1bfdf59bc', 'les_2c77e5eecc318a', 'learn', 2, 'definition', '{"term":"What equilibrium isn''t","body":"It isn''t equal concentrations of reactants and products, and it isn''t a stopped reaction. The ratio described by K is what''s fixed at a given temperature."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf450461b09fcb', 'les_2c77e5eecc318a', 'learn', 3, 'worked_example', '{"title":"N₂O₄ (colorless) ⇌ 2NO₂ (brown) in a sealed tube","steps":[{"latex":"\\text{the color darkens, then stops changing}","explanation":"Equilibrium: NO₂ forms and reacts back at equal rates."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_454b280a0a016f', 'les_2c77e5eecc318a', 'experiment', 4, 'activity', '{"activity":"equilibrium","title":"Equilibrium concentrations aren''t equal","params":{"K":4,"A0":1,"B0":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_637598419fb192', 'les_2c77e5eecc318a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carbonated drinks (CO₂ dissolving and escaping), oxygen binding to hemoglobin, and every industrial process that can''t reach 100% yield."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42f04768e363d0', 'les_2c77e5eecc318a', 1, 'practice', 'multiple_choice', 1, 'At equilibrium,…', '{"choices":["the reaction stops","forward and reverse rates are equal","reactant and product concentrations are equal","only products exist"],"answer":1}', '[]', 'Dynamic balance.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a8db1bfdf59bc', 'les_2c77e5eecc318a', 2, 'practice', 'multiple_choice', 2, 'On a rate–time graph for a reaction starting with only reactants, the forward rate…', '{"choices":["starts at zero","decreases until it meets the reverse rate","increases forever","stays constant"],"answer":1}', '[]', 'Reactants are used up.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf450461b09fcb', 'les_2c77e5eecc318a', 3, 'practice', 'multiple_choice', 2, 'Isotope-labeled atoms added at equilibrium end up in both reactants and products because…', '{"choices":["the system is not at equilibrium","both reactions continue","the label reacts","K changes"],"answer":1}', '[]', 'Evidence of dynamic equilibrium.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_454b280a0a016f', 'les_2c77e5eecc318a', 4, 'review', 'multiple_choice', 3, 'Equilibrium can only be established in…', '{"choices":["an open system","a closed system","a solid","a gas only"],"answer":1}', '[]', 'Products must stay to react back.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2c77e5eecc318a', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2c77e5eecc318a', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: ionic-solids-structure
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_587d4f87865464', 'ionic-solids-structure', 'Structure of ionic solids', 'Describe ionic lattices, compare lattice energies with Coulomb''s law, and explain the properties of ionic solids from their structure.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dbbe56ae4d2fbd', 'les_587d4f87865464', 1, 'Describe the three-dimensional lattice of alternating ions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e24be9a893ee28', 'les_587d4f87865464', 2, 'Compare lattice strength using ion charge and size (Coulomb''s law).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6c726e29a7ff00', 'les_587d4f87865464', 3, 'Explain melting point, brittleness and conductivity from structure.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dbbe56ae4d2fbd', 'les_587d4f87865464', 'learn', 1, 'definition', '{"term":"The lattice","body":"In NaCl each Na⁺ is surrounded by 6 Cl⁻ and vice versa, in a repeating cubic pattern. There are no separate molecules, which is why we write formula units."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e24be9a893ee28', 'les_587d4f87865464', 'learn', 2, 'definition', '{"term":"Lattice energy","body":"The energy holding the lattice together grows with charge and shrinks with distance: $E \\propto \\frac{q_1q_2}{r}$. Doubling both charges (Na⁺Cl⁻ to Mg²⁺O²⁻) roughly quadruples the attraction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c726e29a7ff00', 'les_587d4f87865464', 'learn', 3, 'worked_example', '{"title":"Rank MgO, NaCl and NaF by lattice energy","steps":[{"latex":"\\text{MgO} > \\text{NaF} > \\text{NaCl}","explanation":"MgO has ±2 charges; F⁻ is smaller than Cl⁻. Melting points: 2852, 993 and 801 °C."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fe85edf128925', 'les_587d4f87865464', 'learn', 4, 'definition', '{"term":"Properties","body":"Strong attractions give high melting points and hardness. A shift in the lattice lines up like charges, which repel, so ionic crystals are brittle. They conduct only when melted or dissolved."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85918b0dfb8024', 'les_587d4f87865464', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"MgO lines furnaces because it melts so high; the brittleness of ceramics comes from their ionic bonding."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dbbe56ae4d2fbd', 'les_587d4f87865464', 1, 'practice', 'multiple_choice', 2, 'Which has the largest lattice energy?', '{"choices":["KCl","NaCl","CaO","KBr"],"answer":2}', '[]', '+2 and −2 charges.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e24be9a893ee28', 'les_587d4f87865464', 2, 'practice', 'multiple_choice', 2, 'Why does LiF have a higher melting point than KF?', '{"choices":["Li⁺ is smaller, so ions are closer","Li⁺ has higher charge","F⁻ is larger","KF is molecular"],"answer":0}', '[]', 'Smaller r, larger attraction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6c726e29a7ff00', 'les_587d4f87865464', 3, 'practice', 'multiple_choice', 2, 'Ionic solids shatter when struck because…', '{"choices":["they have no bonds","shifting layers line up like charges, which repel","they''re metals","electrons flow"],"answer":1}', '[]', 'Repulsion splits the crystal.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5fe85edf128925', 'les_587d4f87865464', 4, 'review', 'multiple_choice', 3, 'Solid NaCl doesn''t conduct electricity, but molten NaCl does, because…', '{"choices":["electrons appear when melted","ions become mobile","it becomes metallic","chlorine gas conducts"],"answer":1}', '[]', 'Charge carriers must move.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_587d4f87865464', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: magnitude-of-k
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bd6523a7636ec4', 'magnitude-of-k', 'Magnitude of the equilibrium constant', 'Interpret very large and very small K values, decide when a reaction essentially goes to completion, and separate equilibrium position from reaction rate.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f4902e47aa6f07', 'les_bd6523a7636ec4', 1, 'Interpret K ≫ 1 (products favored) and K ≪ 1 (reactants favored).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7ac442cea4f838', 'les_bd6523a7636ec4', 2, 'Recognize when a reaction effectively goes to completion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_406f7c91c16169', 'les_bd6523a7636ec4', 3, 'Explain why a large K says nothing about how fast equilibrium is reached.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4902e47aa6f07', 'les_bd6523a7636ec4', 'learn', 1, 'definition', '{"term":"Reading K","body":"K ≫ 1 (say above 10³): mostly products at equilibrium. K ≪ 1 (below 10⁻³): mostly reactants. In between, significant amounts of both."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ac442cea4f838', 'les_bd6523a7636ec4', 'learn', 2, 'worked_example', '{"title":"Two reactions at 25 °C","steps":[{"latex":"\\text{N}_2 + \\text{O}_2 \\rightleftharpoons 2\\text{NO},\\ K \\approx 10^{-30}","explanation":"Air doesn''t turn into NO on its own."},{"latex":"\\text{H}^+ + \\text{OH}^- \\rightleftharpoons \\text{H}_2\\text{O},\\ K = 10^{14}","explanation":"Neutralization goes essentially to completion."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_406f7c91c16169', 'les_bd6523a7636ec4', 'learn', 3, 'callout', '{"tone":"warning","title":"K isn''t speed","body":"Burning sugar has an enormous K, yet sugar sits in air for years: the activation energy is high. Thermodynamics says where a reaction ends; kinetics says how fast it gets there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50d34d7aa7035b', 'les_bd6523a7636ec4', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car engines produce NO only because the high temperature raises K for N₂ + O₂; catalytic converters then help it decompose."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4902e47aa6f07', 'les_bd6523a7636ec4', 1, 'practice', 'multiple_choice', 2, 'A reaction has K = 2 × 10⁻⁸. At equilibrium the mixture is…', '{"choices":["mostly products","mostly reactants","equal amounts","empty"],"answer":1}', '[]', 'K ≪ 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ac442cea4f838', 'les_bd6523a7636ec4', 2, 'practice', 'multiple_choice', 2, 'K = 4 × 10¹⁵ means the reaction…', '{"choices":["is fast","essentially goes to completion","barely happens","is at equilibrium immediately"],"answer":1}', '[]', 'Says nothing about rate.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_406f7c91c16169', 'les_bd6523a7636ec4', 3, 'practice', 'multiple_choice', 2, 'If K for A ⇌ B is 10⁵, then K for B ⇌ A is…', '{"choices":["10⁵","10⁻⁵","−10⁵","1"],"answer":1}', '[]', 'Reciprocal.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50d34d7aa7035b', 'les_bd6523a7636ec4', 4, 'review', 'multiple_choice', 3, 'Gasoline and oxygen coexist in a tank despite a huge K for combustion because…', '{"choices":["K is small","the activation energy is high","it''s at equilibrium","oxygen is inert"],"answer":1}', '[]', 'Kinetic stability.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bd6523a7636ec4', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bd6523a7636ec4', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: mass-spectroscopy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_55c1f38f3909dc', 'mass-spectroscopy', 'Mass spectroscopy of elements', 'Read mass spectra of elements, connect peak positions and heights to isotope masses and abundances, and compute average atomic mass.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eaeb0f1bd1bc9e', 'les_55c1f38f3909dc', 1, 'Explain how a mass spectrometer separates ions by mass.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1d010409eb2a9b', 'les_55c1f38f3909dc', 2, 'Read isotope masses and relative abundances from a spectrum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d90f35497c937b', 'les_55c1f38f3909dc', 3, 'Compute the average atomic mass, and interpret spectra of diatomic elements.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eaeb0f1bd1bc9e', 'les_55c1f38f3909dc', 'learn', 1, 'definition', '{"term":"The instrument","body":"Atoms are ionized, accelerated and deflected by a magnetic field; lighter ions bend more. The spectrum plots relative abundance (peak height) against mass-to-charge ratio, giving one peak per isotope."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d010409eb2a9b', 'les_55c1f38f3909dc', 'learn', 2, 'worked_example', '{"title":"Magnesium: peaks at 23.985 (78.99%), 24.986 (10.00%) and 25.983 u (11.01%)","steps":[{"latex":"\\bar m = 0.7899(23.985) + 0.1000(24.986)","explanation":""},{"latex":"\\quad + 0.1101(25.983)","explanation":""},{"latex":"\\bar m \\approx 24.31\\ \\text{u}","explanation":"Matches the periodic table."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d90f35497c937b', 'les_55c1f38f3909dc', 'learn', 3, 'definition', '{"term":"Diatomic elements","body":"Bromine is about 50% Br-79 and 50% Br-81, so Br₂ shows three molecular peaks at 158, 160 and 162 in a 1 : 2 : 1 ratio (79+79, 79+81 or 81+79, 81+81)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec9eebb6b6531a', 'les_55c1f38f3909dc', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Mass spectrometry identifies drugs in blood, detects explosives at airports and measures isotope ratios for dating rocks."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eaeb0f1bd1bc9e', 'les_55c1f38f3909dc', 1, 'practice', 'numeric', 2, 'An element has isotopes at 10.013 u (19.9%) and 11.009 u (80.1%). Find its average atomic mass, to two decimal places.', '{"answer":10.81,"tolerance":0.01,"unit":"u"}', '[]', 'Boron.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1d010409eb2a9b', 'les_55c1f38f3909dc', 2, 'practice', 'multiple_choice', 2, 'A mass spectrum shows two peaks of equal height at 79 and 81. The element is likely…', '{"choices":["Cl","Br","Cu","Se"],"answer":1}', '[]', 'Average about 80.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d90f35497c937b', 'les_55c1f38f3909dc', 3, 'practice', 'multiple_choice', 2, 'What does peak height represent?', '{"choices":["mass","relative abundance","charge","energy"],"answer":1}', '[]', 'How many ions have that mass.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec9eebb6b6531a', 'les_55c1f38f3909dc', 4, 'review', 'multiple_choice', 3, 'Chlorine is about 75% Cl-35 and 25% Cl-37. The Cl₂ peaks at 70, 72 and 74 have a ratio of about…', '{"choices":["1 : 1 : 1","9 : 6 : 1","3 : 1 : 0","1 : 2 : 1"],"answer":1}', '[]', '$0.75^2 : 2(0.75)(0.25) : 0.25^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_55c1f38f3909dc', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));

-- Lesson: metals-alloys
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_835307f8d88dfd', 'metals-alloys', 'Structure of metals and alloys', 'Explain metallic properties with the electron-sea model, and distinguish substitutional and interstitial alloys and their effects on properties.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_15e63afde691bc', 'les_835307f8d88dfd', 1, 'Use the electron-sea model to explain conductivity, malleability and luster.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bc4370e9c8381f', 'les_835307f8d88dfd', 2, 'Distinguish substitutional and interstitial alloys.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4f923a18ef74ae', 'les_835307f8d88dfd', 3, 'Predict how alloying changes hardness and malleability.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15e63afde691bc', 'les_835307f8d88dfd', 'learn', 1, 'definition', '{"term":"Electron sea","body":"Metal atoms release valence electrons into a shared, delocalized \"sea\" around a lattice of cations. Mobile electrons conduct heat and electricity; layers can slide without breaking bonds, so metals are malleable and ductile."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc4370e9c8381f', 'les_835307f8d88dfd', 'learn', 2, 'definition', '{"term":"Alloys","body":"Substitutional alloys replace host atoms with similar-sized ones (brass: Zn in Cu). Interstitial alloys fit much smaller atoms into the gaps (steel: C in Fe). Either way, the different atoms disrupt the sliding of layers, so alloys are harder and less malleable than the pure metal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4f923a18ef74ae', 'les_835307f8d88dfd', 'learn', 3, 'worked_example', '{"title":"Why is steel harder than iron?","steps":[{"latex":"\\text{small C atoms fill gaps between Fe atoms}","explanation":"Layers can''t slide as easily, and the C–Fe interactions add strength."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ab9b6221090ea', 'les_835307f8d88dfd', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Stainless steel (Cr and Ni added), bronze, solder, and gold jewelry alloyed with copper so it doesn''t bend."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_15e63afde691bc', 'les_835307f8d88dfd', 1, 'practice', 'multiple_choice', 2, 'Brass (copper and zinc of similar size) is…', '{"choices":["interstitial","substitutional","ionic","a compound"],"answer":1}', '[]', 'Zn takes Cu''s places.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc4370e9c8381f', 'les_835307f8d88dfd', 2, 'practice', 'multiple_choice', 2, 'Metals conduct electricity because…', '{"choices":["ions move","valence electrons are delocalized","they''re polar","of hydrogen bonding"],"answer":1}', '[]', 'Electron sea.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4f923a18ef74ae', 'les_835307f8d88dfd', 3, 'practice', 'multiple_choice', 2, 'Adding carbon to iron makes it…', '{"choices":["softer","harder and less malleable","a better conductor","ionic"],"answer":1}', '[]', 'Interstitial atoms block slipping.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ab9b6221090ea', 'les_835307f8d88dfd', 4, 'review', 'multiple_choice', 3, 'Which property is NOT explained by the electron-sea model?', '{"choices":["conductivity","malleability","luster","brittleness"],"answer":3}', '[]', 'Metals aren''t brittle.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_835307f8d88dfd', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: multistep-energy-profile
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5fea02a41fd0a3', 'multistep-energy-profile', 'Multistep reaction energy profile', 'Interpret energy profiles with several peaks: count steps, locate intermediates in the valleys, and identify the rate-determining step from the largest barrier.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9cb6396d73d05d', 'les_5fea02a41fd0a3', 1, 'Count elementary steps from the number of peaks.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_077689c64836cb', 'les_5fea02a41fd0a3', 2, 'Locate intermediates (valleys) and transition states (peaks).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e59b67a7b160d9', 'les_5fea02a41fd0a3', 3, 'Identify the rate-determining step as the one with the largest activation energy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9cb6396d73d05d', 'les_5fea02a41fd0a3', 'learn', 1, 'definition', '{"term":"Reading the curve","body":"Each peak is a transition state, one per elementary step. Valleys between peaks are intermediates, which are short-lived but real. The step with the biggest climb from its own starting valley is the slowest: the rate-determining step."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_077689c64836cb', 'les_5fea02a41fd0a3', 'learn', 2, 'worked_example', '{"title":"A profile has two peaks: 40 kJ above the reactants, then 70 kJ above the intermediate valley","steps":[{"latex":"2\\ \\text{peaks} \\Rightarrow 2\\ \\text{steps},\\ 1\\ \\text{intermediate}","explanation":""},{"latex":"E_{a,2} > E_{a,1}","explanation":"Step 2 has the larger barrier, so it''s rate-determining."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e59b67a7b160d9', 'les_5fea02a41fd0a3', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Enzyme diagrams have several humps, and catalysts change the shape by replacing one big hump with several small ones."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9cb6396d73d05d', 'les_5fea02a41fd0a3', 1, 'practice', 'multiple_choice', 2, 'An energy profile with three peaks represents…', '{"choices":["three intermediates","three elementary steps","one step","two catalysts"],"answer":1}', '[]', 'One transition state per step.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_077689c64836cb', 'les_5fea02a41fd0a3', 2, 'practice', 'multiple_choice', 2, 'How many intermediates are in a three-step mechanism?', '{"choices":["1","2","3","0"],"answer":1}', '[]', 'The valleys between peaks.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e59b67a7b160d9', 'les_5fea02a41fd0a3', 3, 'practice', 'multiple_choice', 2, 'The rate-determining step is the one with…', '{"choices":["the highest peak in absolute energy","the largest activation energy from its own starting point","the lowest valley","the most products"],"answer":1}', '[]', 'Measure each climb.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_175701f3b849d7', 'les_5fea02a41fd0a3', 4, 'review', 'multiple_choice', 3, 'Overall ΔH in a multistep profile equals…', '{"choices":["the sum of the Eₐ values","the energy of products minus reactants","the highest peak","zero"],"answer":1}', '[]', 'Intermediate steps cancel.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5fea02a41fd0a3', (SELECT id FROM concepts WHERE slug = 'kinetics'));

-- Lesson: net-ionic-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_28c9856477f7a0', 'net-ionic-equations', 'Net ionic equations', 'Write molecular, complete ionic and net ionic equations, identify spectator ions, and use them in precipitation stoichiometry.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_204c6b7c928726', 'les_28c9856477f7a0', 1, 'Split strong electrolytes into ions; keep solids, liquids, gases and weak electrolytes together.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_62894e06e47adf', 'les_28c9856477f7a0', 2, 'Cancel spectator ions to write net ionic equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9aa4e6ea3828c2', 'les_28c9856477f7a0', 3, 'Compute precipitate masses from net ionic equations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_204c6b7c928726', 'les_28c9856477f7a0', 'learn', 1, 'definition', '{"term":"Three levels","body":"Molecular: AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq). Complete ionic: split every soluble strong electrolyte into ions. Net ionic: remove the spectator ions that appear unchanged on both sides."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62894e06e47adf', 'les_28c9856477f7a0', 'learn', 2, 'worked_example', '{"title":"Silver nitrate plus sodium chloride","steps":[{"latex":"\\text{Ag}^+ + \\text{NO}_3^- + \\text{Na}^+ + \\text{Cl}^- \\to","explanation":"Complete ionic equation."},{"latex":"\\text{AgCl}(s) + \\text{Na}^+ + \\text{NO}_3^-","explanation":""},{"latex":"\\text{Ag}^+(aq) + \\text{Cl}^-(aq) \\to \\text{AgCl}(s)","explanation":"Net ionic: Na⁺ and NO₃⁻ are spectators."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9aa4e6ea3828c2', 'les_28c9856477f7a0', 'learn', 3, 'worked_example', '{"title":"Mass of AgCl from 50.0 mL of 0.100 M AgNO₃ with excess NaCl","steps":[{"latex":"n_{\\text{Ag}^+} = 0.0500(0.100) = 0.00500\\ \\text{mol}","explanation":""},{"latex":"m = 0.00500(143.32) \\approx 0.717\\ \\text{g}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9e34aeaf419e05', 'les_28c9856477f7a0', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Removing lead from water by precipitation, gravimetric analysis, and kidney stones (calcium oxalate precipitating)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_204c6b7c928726', 'les_28c9856477f7a0', 1, 'practice', 'multiple_choice', 2, 'What is the net ionic equation for HCl(aq) + NaOH(aq)?', '{"choices":["HCl + NaOH → NaCl + H₂O","H⁺ + OH⁻ → H₂O","Na⁺ + Cl⁻ → NaCl","H⁺ + Cl⁻ → HCl"],"answer":1}', '[]', 'Na⁺ and Cl⁻ are spectators.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62894e06e47adf', 'les_28c9856477f7a0', 2, 'practice', 'multiple_choice', 2, 'In Pb(NO₃)₂(aq) + 2KI(aq) → PbI₂(s) + 2KNO₃(aq), the spectators are…', '{"choices":["Pb²⁺ and I⁻","K⁺ and NO₃⁻","Pb²⁺ and K⁺","none"],"answer":1}', '[]', 'They stay dissolved.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9aa4e6ea3828c2', 'les_28c9856477f7a0', 3, 'practice', 'numeric', 3, 'How many grams of PbI₂ (461.0 g/mol) form from 25.0 mL of 0.200 M Pb(NO₃)₂ with excess KI? Two decimal places.', '{"answer":2.31,"tolerance":0.01,"unit":"g"}', '[]', '$0.00500$ mol $\times 461.0 = 2.305$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9e34aeaf419e05', 'les_28c9856477f7a0', 4, 'review', 'multiple_choice', 3, 'Why is acetic acid written as a molecule (CH₃COOH) in a net ionic equation?', '{"choices":["it''s insoluble","it''s a weak electrolyte, mostly un-ionized","it''s a gas","it''s a strong acid"],"answer":1}', '[]', 'Only strong electrolytes are split.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_28c9856477f7a0', (SELECT id FROM concepts WHERE slug = 'chemical-reactions'));

-- Lesson: oxidation-numbers-redox
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_87a315c78dd1d0', 'oxidation-numbers-redox', 'Oxidation numbers and redox reactions', 'Assign oxidation numbers, identify what is oxidized and reduced, and balance redox reactions in acidic solution by the half-reaction method.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6d126d6a830e25', 'les_87a315c78dd1d0', 1, 'Assign oxidation numbers with the standard rules.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4712ccfe6b7f9d', 'les_87a315c78dd1d0', 2, 'Identify oxidation, reduction, oxidizing agents and reducing agents.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8bdda8c5c18566', 'les_87a315c78dd1d0', 3, 'Balance redox equations in acid with half-reactions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d126d6a830e25', 'les_87a315c78dd1d0', 'learn', 1, 'definition', '{"term":"Oxidation numbers","body":"Elements are 0; monatomic ions equal their charge; O is usually −2 and H +1 (with nonmetals); F is always −1; the numbers sum to the overall charge. Oxidation is loss of electrons (the number rises); reduction is gain (the number falls): \"OIL RIG\"."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4712ccfe6b7f9d', 'les_87a315c78dd1d0', 'learn', 2, 'worked_example', '{"title":"Find the oxidation numbers of S in H₂SO₄ and Mn in KMnO₄","steps":[{"latex":"2(+1) + S + 4(-2) = 0 \\Rightarrow S = +6","explanation":""},{"latex":"+1 + \\text{Mn} + 4(-2) = 0 \\Rightarrow \\text{Mn} = +7","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8bdda8c5c18566', 'les_87a315c78dd1d0', 'learn', 3, 'definition', '{"term":"Half-reactions in acid","body":"Split into oxidation and reduction; balance atoms other than O and H; add H₂O for O, H⁺ for H, and electrons for charge; multiply so electrons cancel; add."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd2a49f1efbbd6', 'les_87a315c78dd1d0', 'learn', 4, 'worked_example', '{"title":"MnO₄⁻ + Fe²⁺ → Mn²⁺ + Fe³⁺ (acidic)","steps":[{"latex":"\\text{MnO}_4^- + 8\\text{H}^+ + 5e^- \\to \\text{Mn}^{2+} + 4\\text{H}_2\\text{O}","explanation":"Reduction."},{"latex":"5\\text{Fe}^{2+} \\to 5\\text{Fe}^{3+} + 5e^-","explanation":"Oxidation, ×5."},{"latex":"\\text{MnO}_4^- + 8\\text{H}^+ + 5\\text{Fe}^{2+} \\to","explanation":"Add them; electrons cancel."},{"latex":"\\text{Mn}^{2+} + 4\\text{H}_2\\text{O} + 5\\text{Fe}^{3+}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5c8e278db3d6e3', 'les_87a315c78dd1d0', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rusting, batteries, bleach, photosynthesis and respiration are all redox; this reaction (permanganate with iron) is a classic titration for iron content."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6d126d6a830e25', 'les_87a315c78dd1d0', 1, 'practice', 'numeric', 2, 'Find the oxidation number of Cr in Cr₂O₇²⁻.', '{"answer":6}', '[]', '$2\text{Cr} + 7(-2) = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4712ccfe6b7f9d', 'les_87a315c78dd1d0', 2, 'practice', 'multiple_choice', 2, 'In Zn + Cu²⁺ → Zn²⁺ + Cu, the oxidizing agent is…', '{"choices":["Zn","Cu²⁺","Zn²⁺","Cu"],"answer":1}', '[]', 'It gets reduced.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8bdda8c5c18566', 'les_87a315c78dd1d0', 3, 'practice', 'numeric', 3, 'Balance Cu + NO₃⁻ → Cu²⁺ + NO in acid. How many H⁺ appear in the balanced equation (lowest whole numbers)?', '{"answer":8}', '[]', '$3\text{Cu} + 2\text{NO}_3^- + 8\text{H}^+ \to 3\text{Cu}^{2+} + 2\text{NO} + 4\text{H}_2\text{O}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd2a49f1efbbd6', 'les_87a315c78dd1d0', 4, 'review', 'multiple_choice', 3, 'Which change is a reduction?', '{"choices":["Fe²⁺ → Fe³⁺","Cl⁻ → Cl₂","O₂ → O²⁻","Na → Na⁺"],"answer":2}', '[]', 'Oxidation number falls from 0 to −2.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_15e1fc516df8df', 'subj_chem', 'electrochemistry', 'Electrochemistry', 'Redox reactions and the cells that convert chemical and electrical energy.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_87a315c78dd1d0', (SELECT id FROM concepts WHERE slug = 'electrochemistry'));

-- Lesson: ph-solubility
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_23492fd5c8a643', 'ph-solubility', 'pH and solubility', 'Predict how pH changes the solubility of hydroxides and of salts with basic anions, and calculate solubility at a given pH.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ac844a756e7ea2', 'les_23492fd5c8a643', 1, 'Explain why salts with basic anions (OH⁻, CO₃²⁻, F⁻) dissolve better in acid.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0319915b1c1f16', 'les_23492fd5c8a643', 2, 'Calculate hydroxide solubility at a fixed pH.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_546f70c8d51237', 'les_23492fd5c8a643', 3, 'Recognize that salts of strong-acid anions (Cl⁻, NO₃⁻) are unaffected.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac844a756e7ea2', 'les_23492fd5c8a643', 'learn', 1, 'definition', '{"term":"Why pH matters","body":"If a salt''s anion is a base, H⁺ removes it (OH⁻ → H₂O, CO₃²⁻ → HCO₃⁻), pulling the dissolving equilibrium forward. Lower pH means more solubility. Anions of strong acids (Cl⁻) don''t react with H⁺, so their salts aren''t affected."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0319915b1c1f16', 'les_23492fd5c8a643', 'learn', 2, 'worked_example', '{"title":"Mg(OH)₂ (Ksp = 5.6 × 10⁻¹²)","steps":[{"latex":"4s^3 = K_{sp} \\Rightarrow s = 1.1\\times10^{-4}\\ \\text{M}","explanation":"In pure water."},{"latex":"s = \\tfrac{K_{sp}}{(10^{-4})^2} = 5.6\\times10^{-4}\\ \\text{M}","explanation":"Buffered at pH 10, so [OH⁻] is fixed at 10⁻⁴ M."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_546f70c8d51237', 'les_23492fd5c8a643', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Acid rain dissolves limestone and marble; tooth enamel (a hydroxide mineral) erodes in acidic drinks; antacids like Mg(OH)₂ dissolve in stomach acid."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ac844a756e7ea2', 'les_23492fd5c8a643', 1, 'practice', 'numeric', 3, 'Find the solubility of Mg(OH)₂ in a solution buffered at pH 9, in units of $10^{-2}$ M.', '{"answer":5.6,"tolerance":0.01}', '[]', '$[\text{OH}^-] = 10^{-5}$; $\frac{5.6\times10^{-12}}{10^{-10}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0319915b1c1f16', 'les_23492fd5c8a643', 2, 'practice', 'multiple_choice', 2, 'Which salt is more soluble in acidic solution than in pure water?', '{"choices":["AgCl","CaCO₃","NaNO₃","KCl"],"answer":1}', '[]', 'Carbonate is a base.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_546f70c8d51237', 'les_23492fd5c8a643', 3, 'practice', 'multiple_choice', 2, 'Lowering the pH of a saturated Mg(OH)₂ solution…', '{"choices":["decreases solubility","increases solubility","has no effect","precipitates MgCl₂"],"answer":1}', '[]', 'H⁺ removes OH⁻.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22551ca5d6f7e1', 'les_23492fd5c8a643', 4, 'review', 'multiple_choice', 3, 'AgCl''s solubility barely changes with pH because Cl⁻…', '{"choices":["is very basic","is the conjugate base of a strong acid","is insoluble","is a cation"],"answer":1}', '[]', 'It has essentially no affinity for H⁺.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_23492fd5c8a643', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_23492fd5c8a643', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_23492fd5c8a643', (SELECT id FROM formulas WHERE slug = 'ph-scale'), 2);

-- Lesson: phase-change-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6d9159a99ebc9c', 'phase-change-energy', 'Energy of phase changes', 'Use molar enthalpies of fusion and vaporization, read heating curves, and compute the total energy to take a substance through several phases.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3719e07014de1f', 'les_6d9159a99ebc9c', 1, 'Use ΔH_fus and ΔH_vap per mole.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f608b163ee827', 'les_6d9159a99ebc9c', 2, 'Interpret flat (phase change) and sloped (warming) regions of a heating curve.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4bd47608289437', 'les_6d9159a99ebc9c', 3, 'Add up the energy for multi-step heating, and relate ΔH_vap to IMF strength.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3719e07014de1f', 'les_6d9159a99ebc9c', 'learn', 1, 'definition', '{"term":"Molar enthalpies","body":"For water, $\\Delta H_{fus} = 6.01$ kJ/mol and $\\Delta H_{vap} = 40.7$ kJ/mol. Vaporizing takes far more energy than melting because it separates molecules completely, overcoming all their intermolecular forces."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f608b163ee827', 'les_6d9159a99ebc9c', 'learn', 2, 'worked_example', '{"title":"Heat 18.0 g (1.00 mol) of ice at −10 °C into steam at 110 °C","steps":[{"latex":"\\text{ice: } 18.0(2.09)(10) = 0.38\\ \\text{kJ}","explanation":""},{"latex":"6.01\\ \\text{kJ}","explanation":"Melting."},{"latex":"18.0(4.184)(100) = 7.53\\ \\text{kJ}","explanation":"Warming the water to 100 °C."},{"latex":"40.7\\ \\text{kJ}","explanation":"Boiling."},{"latex":"18.0(2.01)(10) = 0.36\\ \\text{kJ}","explanation":"Warming the steam."},{"latex":"q_{total} \\approx 55.0\\ \\text{kJ}","explanation":"Boiling is three-quarters of it."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4bd47608289437', 'les_6d9159a99ebc9c', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Sweating cools you by evaporation; steam burns are worse than boiling-water burns; refrigerators move heat by evaporating and condensing a refrigerant."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3719e07014de1f', 'les_6d9159a99ebc9c', 1, 'practice', 'numeric', 2, 'How much energy melts 36.0 g of ice at 0 °C, in kJ?', '{"answer":12.02,"tolerance":0.01,"unit":"kJ"}', '[]', '2.00 mol × 6.01.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f608b163ee827', 'les_6d9159a99ebc9c', 2, 'practice', 'numeric', 2, 'How much energy vaporizes 9.0 g of water at 100 °C, in kJ, to one decimal place?', '{"answer":20.3,"tolerance":0.1,"unit":"kJ"}', '[]', '0.50 mol × 40.7 = 20.35.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4bd47608289437', 'les_6d9159a99ebc9c', 3, 'practice', 'multiple_choice', 2, 'On a heating curve, a flat segment means…', '{"choices":["no heat is added","a phase change is happening","the substance is cooling","the temperature is rising fast"],"answer":1}', '[]', 'Energy goes into separating particles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ea10d510b28a2', 'les_6d9159a99ebc9c', 4, 'review', 'multiple_choice', 3, 'Which has the highest ΔH_vap?', '{"choices":["CH₄","H₂O","Ne","N₂"],"answer":1}', '[]', 'Hydrogen bonding.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6d9159a99ebc9c', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6d9159a99ebc9c', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: photoelectron-spectroscopy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ed7c9e7ebbc656', 'photoelectron-spectroscopy', 'Photoelectron spectroscopy', 'Interpret photoelectron spectra: peak positions give subshell binding energies, peak heights give electron counts, and Coulomb''s law explains the trends.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_00052999895ff0', 'les_ed7c9e7ebbc656', 1, 'Explain how PES measures the energy needed to remove electrons from each subshell.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f339843d74c4f3', 'les_ed7c9e7ebbc656', 2, 'Read electron configurations from PES peaks.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f1036e20760fe8', 'les_ed7c9e7ebbc656', 3, 'Explain binding-energy trends with Coulomb''s law and shielding.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_00052999895ff0', 'les_ed7c9e7ebbc656', 'learn', 1, 'definition', '{"term":"The method","body":"High-energy photons knock electrons out of atoms. Measuring their kinetic energy gives the binding energy: $BE = h\\nu - KE$. Each subshell gives one peak; its height is proportional to the number of electrons in that subshell."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f339843d74c4f3', 'les_ed7c9e7ebbc656', 'learn', 2, 'definition', '{"term":"Coulomb''s law at work","body":"$F \\propto \\frac{q_1q_2}{r^2}$: electrons closer to the nucleus (lower n) and atoms with more protons have higher binding energies. Inner electrons shield outer ones, so valence electrons are held far more weakly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f1036e20760fe8', 'les_ed7c9e7ebbc656', 'learn', 3, 'worked_example', '{"title":"Oxygen''s spectrum has peaks at 52.6, 3.04 and 1.31 MJ/mol with heights 2 : 2 : 4","steps":[{"latex":"1s^2\\ 2s^2\\ 2p^4","explanation":"High-energy peak = core 1s; the 2p peak is twice as tall as 2s."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1df783d3729b0', 'les_ed7c9e7ebbc656', 'experiment', 4, 'activity', '{"activity":"pes","title":"Compare elements'' spectra","params":{"element":"O"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f026e3f38a32f3', 'les_ed7c9e7ebbc656', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Step from O to F to Ne: every peak shifts to higher energy because the nuclear charge grows. Then go to Na: a new, very low peak (3s) appears."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92af52e036ae8d', 'les_ed7c9e7ebbc656', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"X-ray photoelectron spectroscopy analyzes the chemical makeup of surfaces in chip manufacturing and corrosion research."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_00052999895ff0', 'les_ed7c9e7ebbc656', 1, 'practice', 'multiple_choice', 2, 'A PES spectrum has peaks with relative heights 2, 2, 6, 1. The element is…', '{"choices":["Ne","Na","Mg","F"],"answer":1}', '[]', '1s² 2s² 2p⁶ 3s¹.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f339843d74c4f3', 'les_ed7c9e7ebbc656', 2, 'practice', 'multiple_choice', 2, 'Why is Ne''s 1s peak at higher energy than F''s?', '{"choices":["more electrons","a greater nuclear charge","a larger radius","more shielding"],"answer":1}', '[]', '10 protons vs 9.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f1036e20760fe8', 'les_ed7c9e7ebbc656', 3, 'practice', 'multiple_choice', 2, 'In a spectrum, which peak sits at the lowest binding energy?', '{"choices":["1s","the core electrons","the valence electrons","they''re all equal"],"answer":2}', '[]', 'Farthest out and most shielded.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a1df783d3729b0', 'les_ed7c9e7ebbc656', 4, 'review', 'multiple_choice', 3, 'Two peaks with a height ratio of 1 : 3 in the same shell would be…', '{"choices":["1s² and 2s²","2s² and 2p⁶","2p⁶ and 3s²","impossible"],"answer":1}', '[]', '2 : 6 = 1 : 3.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ed7c9e7ebbc656', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ed7c9e7ebbc656', (SELECT id FROM formulas WHERE slug = 'photon-energy'), 1);

-- Lesson: properties-of-k
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8687c396fe02f2', 'properties-of-k', 'Properties of the equilibrium constant', 'Manipulate K when reactions are reversed, multiplied by a factor or added together.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a8a843aa6dc05f', 'les_8687c396fe02f2', 1, 'Reverse a reaction: K'' = 1/K.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7be16e5a22483e', 'les_8687c396fe02f2', 2, 'Multiply coefficients by n: K'' = Kⁿ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_da65146320a41f', 'les_8687c396fe02f2', 3, 'Add reactions: multiply their K values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8a843aa6dc05f', 'les_8687c396fe02f2', 'learn', 1, 'definition', '{"term":"Rules","body":"Reversing a reaction inverts K. Multiplying all coefficients by n raises K to the nth power (halving the coefficients takes the square root). Adding reactions multiplies their K values; compare Hess''s law, where ΔH values add."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7be16e5a22483e', 'les_8687c396fe02f2', 'learn', 2, 'worked_example', '{"title":"A ⇌ B has K₁ = 4.0; B ⇌ C has K₂ = 0.50","steps":[{"latex":"\\text{A} \\rightleftharpoons \\text{C}:\\ K = 4.0(0.50) = 2.0","explanation":""},{"latex":"2\\text{A} \\rightleftharpoons 2\\text{B}:\\ K = 4.0^2 = 16","explanation":""},{"latex":"\\text{B} \\rightleftharpoons \\text{A}:\\ K = \\tfrac{1}{4.0} = 0.25","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da65146320a41f', 'les_8687c396fe02f2', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Combining tabulated K values (acid dissociation, solubility, complex formation) gives K for reactions that were never measured directly."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a8a843aa6dc05f', 'les_8687c396fe02f2', 1, 'practice', 'numeric', 2, 'N₂ + 3H₂ ⇌ 2NH₃ has K = 0.50. Find K for 2NH₃ ⇌ N₂ + 3H₂.', '{"answer":2}', '[]', '$\frac{1}{0.50}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7be16e5a22483e', 'les_8687c396fe02f2', 2, 'practice', 'numeric', 2, 'Find K for ½N₂ + 3/2 H₂ ⇌ NH₃, to two decimal places.', '{"answer":0.71,"tolerance":0.01}', '[]', '$\sqrt{0.50}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da65146320a41f', 'les_8687c396fe02f2', 3, 'practice', 'numeric', 3, 'Reaction 1 has K = 1.0 × 10⁻⁵; reaction 2 has K = 2.0 × 10³. Find K for their sum.', '{"answer":0.02,"tolerance":0.0001}', '[]', 'Multiply.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d1dc962847b5e2', 'les_8687c396fe02f2', 4, 'review', 'multiple_choice', 3, 'When reactions are added, their K values…', '{"choices":["add","multiply","subtract","average"],"answer":1}', '[]', 'Exponent rules from the K expressions.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8687c396fe02f2', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8687c396fe02f2', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: properties-of-solids
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_174577308f930a', 'properties-of-solids', 'Properties of solids', 'Classify solids as ionic, molecular, covalent network or metallic, and predict melting point, hardness and conductivity from the particles and forces involved.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_61b12e179c7655', 'les_174577308f930a', 1, 'Classify solids by their particles and the forces between them.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c1541693a59e50', 'les_174577308f930a', 2, 'Predict relative melting points and hardness.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4fd2044b04eda3', 'les_174577308f930a', 3, 'Predict electrical conductivity in each type, solid and melted.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61b12e179c7655', 'les_174577308f930a', 'learn', 1, 'definition', '{"term":"Four types","body":"Ionic (NaCl): ions held by ionic bonds; high melting point, brittle, conducts when molten. Molecular (ice, sugar): molecules held by intermolecular forces; low melting point, soft, nonconducting. Covalent network (diamond, SiO₂): atoms joined by covalent bonds throughout; very high melting point, very hard. Metallic (Cu): cations in an electron sea; conducts, malleable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1541693a59e50', 'les_174577308f930a', 'learn', 2, 'worked_example', '{"title":"Why does SiO₂ melt at 1713 °C while CO₂ sublimes at −78 °C?","steps":[{"latex":"\\text{SiO}_2:\\ \\text{covalent network}","explanation":"Melting breaks covalent bonds."},{"latex":"\\text{CO}_2:\\ \\text{molecular}","explanation":"Only weak dispersion forces separate the molecules."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fd2044b04eda3', 'les_174577308f930a', 'learn', 3, 'callout', '{"tone":"note","title":"Crystalline vs amorphous","body":"Crystalline solids have long-range order and sharp melting points; amorphous solids (glass, many plastics) soften over a temperature range."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9f329a5af9373', 'les_174577308f930a', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Diamond cutting tools (network), silicon chips (network semiconductor), and why sugar melts in a pan while salt doesn''t."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_61b12e179c7655', 'les_174577308f930a', 1, 'practice', 'multiple_choice', 2, 'A solid melts at 1400 °C and doesn''t conduct, solid or melted. It''s most likely…', '{"choices":["ionic","molecular","covalent network","metallic"],"answer":2}', '[]', 'Molten ionic solids conduct.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c1541693a59e50', 'les_174577308f930a', 2, 'practice', 'multiple_choice', 2, 'Which has the lowest melting point?', '{"choices":["NaCl","diamond","I₂","Fe"],"answer":2}', '[]', 'Molecular solid.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4fd2044b04eda3', 'les_174577308f930a', 3, 'practice', 'multiple_choice', 2, 'Graphite conducts electricity because…', '{"choices":["it''s ionic","delocalized electrons move along its layers","it''s metallic","of hydrogen bonds"],"answer":1}', '[]', 'Each C uses three bonds; the fourth electron is delocalized.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a9f329a5af9373', 'les_174577308f930a', 4, 'review', 'multiple_choice', 3, 'What holds a molecular solid together?', '{"choices":["covalent bonds between molecules","intermolecular forces","ionic bonds","an electron sea"],"answer":1}', '[]', 'Covalent bonds are inside each molecule.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_174577308f930a', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: q-le-chatelier
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f390915980c011', 'q-le-chatelier', 'Reaction quotient and Le Châtelier''s principle', 'Explain Le Châtelier shifts quantitatively by showing how a stress changes Q relative to K, including volume changes and the effect of temperature on K.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_294ee69b6421bb', 'les_f390915980c011', 1, 'Show that adding or removing a species makes Q ≠ K, and predict the shift.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6a8f1d77339489', 'les_f390915980c011', 2, 'Explain volume and pressure changes through their effect on Q.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_488c24eedb07b4', 'les_f390915980c011', 3, 'Explain that temperature changes K itself (endothermic direction favored by heating).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_294ee69b6421bb', 'les_f390915980c011', 'learn', 1, 'definition', '{"term":"Stress changes Q","body":"Adding reactant lowers Q below K, so the reaction shifts forward. Removing product does the same. The system shifts until Q equals K again."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a8f1d77339489', 'les_f390915980c011', 'learn', 2, 'worked_example', '{"title":"2NO₂ ⇌ N₂O₄: the volume doubles at constant temperature","steps":[{"latex":"Q'' = \\tfrac{c/2}{(c/2)^2} = 2Q","explanation":"Every concentration halves."},{"latex":"Q'' > K \\Rightarrow \\text{shifts left}","explanation":"Toward more gas moles, as Le Châtelier predicts."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_488c24eedb07b4', 'les_f390915980c011', 'learn', 3, 'definition', '{"term":"Temperature is different","body":"Temperature changes K, not Q. For an exothermic reaction, heating lowers K (shift toward reactants); for an endothermic one, heating raises K. Adding an inert gas at constant volume changes nothing, since no partial pressures change."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_53936f3455a715', 'les_f390915980c011', 'experiment', 4, 'activity', '{"activity":"equilibrium","title":"Add a species, then compare Q with K","params":{"K":4,"A0":1,"B0":1,"amount":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b2b91c5f5ac680', 'les_f390915980c011', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ammonia plants remove NH₃ as it forms to keep Q below K, and hemoglobin releases O₂ in tissues where its concentration is low."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_294ee69b6421bb', 'les_f390915980c011', 1, 'practice', 'multiple_choice', 2, 'Removing product from a system at equilibrium makes Q…', '{"choices":["larger than K","smaller than K","equal to K","zero"],"answer":1}', '[]', 'The numerator shrinks.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a8f1d77339489', 'les_f390915980c011', 2, 'practice', 'multiple_choice', 2, 'For an exothermic reaction, raising the temperature…', '{"choices":["raises K","lowers K","doesn''t change K","stops the reaction"],"answer":1}', '[]', 'Heat acts like a product.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_488c24eedb07b4', 'les_f390915980c011', 3, 'practice', 'multiple_choice', 2, 'Adding argon to a rigid container at equilibrium…', '{"choices":["shifts it right","shifts it left","has no effect","changes K"],"answer":2}', '[]', 'Partial pressures are unchanged.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_53936f3455a715', 'les_f390915980c011', 4, 'review', 'multiple_choice', 3, 'For H₂ + I₂ ⇌ 2HI (all gases), compressing the container…', '{"choices":["shifts right","shifts left","doesn''t shift","changes K"],"answer":2}', '[]', 'Equal gas moles on both sides: Q is unchanged.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f390915980c011', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f390915980c011', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: quantum-numbers-orbitals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b226556ce0d5c9', 'quantum-numbers-orbitals', 'Quantum numbers and orbitals', 'Describe electrons with the four quantum numbers, relate them to orbital shapes and capacities, and decide which sets are allowed.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6cc4920ada0f6c', 'les_b226556ce0d5c9', 1, 'State the meaning and allowed values of n, ℓ, m_ℓ and m_s.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2dfc42128c9ec8', 'les_b226556ce0d5c9', 2, 'Count orbitals and electrons in a level or sublevel.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f588cbdf30f08b', 'les_b226556ce0d5c9', 3, 'Identify allowed and forbidden quantum-number sets.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6cc4920ada0f6c', 'les_b226556ce0d5c9', 'learn', 1, 'definition', '{"term":"The four quantum numbers","body":"Principal $n = 1, 2, 3, \\ldots$: energy level and size. Angular momentum $\\ell = 0, \\ldots, n - 1$: sublevel shape (0 = s, 1 = p, 2 = d, 3 = f). Magnetic $m_\\ell = -\\ell, \\ldots, +\\ell$: orientation, one value per orbital. Spin $m_s = \\pm\\frac12$. By the Pauli exclusion principle, no two electrons share all four."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2dfc42128c9ec8', 'les_b226556ce0d5c9', 'learn', 2, 'definition', '{"term":"Counting","body":"A sublevel has $2\\ell + 1$ orbitals; level n has $n^2$ orbitals and holds $2n^2$ electrons. Orbitals are probability clouds: s orbitals are spheres, p orbitals dumbbells along x, y and z, d orbitals mostly four-lobed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f588cbdf30f08b', 'les_b226556ce0d5c9', 'learn', 3, 'worked_example', '{"title":"The n = 3 level","steps":[{"latex":"\\ell = 0, 1, 2 \\Rightarrow 3s,\\ 3p,\\ 3d","explanation":""},{"latex":"1 + 3 + 5 = 9\\ \\text{orbitals},\\ 18\\ \\text{electrons}","explanation":"$n^2$ and $2n^2$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2999c1ebd75d21', 'les_b226556ce0d5c9', 'learn', 4, 'worked_example', '{"title":"Is (n, ℓ, m_ℓ, m_s) = (2, 2, 0, +½) allowed?","steps":[{"latex":"\\ell \\le n - 1 = 1","explanation":"No: ℓ = 2 needs n ≥ 3."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1190a681d1fb8e', 'les_b226556ce0d5c9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"MRI depends on nuclear spin, and the 2p and 3d orbital shapes explain the bond angles in molecules and the colors of gemstones."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6cc4920ada0f6c', 'les_b226556ce0d5c9', 1, 'practice', 'numeric', 2, 'How many orbitals are in the 4f sublevel?', '{"answer":7}', '[]', '$\ell = 3$: $2(3) + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2dfc42128c9ec8', 'les_b226556ce0d5c9', 2, 'practice', 'numeric', 2, 'What is the maximum number of electrons with n = 4?', '{"answer":32}', '[]', '$2n^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f588cbdf30f08b', 'les_b226556ce0d5c9', 3, 'practice', 'multiple_choice', 2, 'Which set is allowed?', '{"choices":["(1, 1, 0, +½)","(3, 2, −3, −½)","(4, 2, −2, +½)","(2, 0, 1, +½)"],"answer":2}', '[]', 'ℓ < n and |m_ℓ| ≤ ℓ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2999c1ebd75d21', 'les_b226556ce0d5c9', 4, 'review', 'multiple_choice', 3, 'Which quantum number describes an orbital''s shape?', '{"choices":["n","ℓ","m_ℓ","m_s"],"answer":1}', '[]', 's, p, d, f.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b226556ce0d5c9', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));

-- Lesson: rate-laws
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ba5e448d9ff34f', 'rate-laws', 'Rate laws', 'Determine rate laws from initial-rate data, find rate constants and their units, and use integrated rate laws and half-lives.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cb8d7711902316', 'les_ba5e448d9ff34f', 1, 'Find reaction orders by the method of initial rates.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b6b44bc8d3022', 'les_ba5e448d9ff34f', 2, 'Compute k and its units from a rate law.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_255dc041e26047', 'les_ba5e448d9ff34f', 3, 'Use integrated rate laws and identify order from linear plots ([A], ln[A] or 1/[A] vs t).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb8d7711902316', 'les_ba5e448d9ff34f', 'learn', 1, 'definition', '{"term":"Rate laws","body":"$\\text{rate} = k[A]^m[B]^n$. The orders m and n come from experiments, not from coefficients. Doubling [A] at first order doubles the rate; at second order, quadruples it; at zero order, leaves it unchanged."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b6b44bc8d3022', 'les_ba5e448d9ff34f', 'learn', 2, 'worked_example', '{"title":"Initial rates for A + B → C","steps":[{"latex":"[A]\\ \\times2,\\ [B]\\ \\text{fixed}:\\ \\text{rate}\\ \\times4 \\Rightarrow m = 2","explanation":"Experiments 1 and 2."},{"latex":"[B]\\ \\times2,\\ [A]\\ \\text{fixed}:\\ \\text{rate}\\ \\times2 \\Rightarrow n = 1","explanation":"Experiments 1 and 3."},{"latex":"k = \\tfrac{0.0020}{(0.10)^2(0.20)} = 1.0\\ \\text{M}^{-2}\\text{s}^{-1}","explanation":"From experiment 1: [A] = 0.10 M, [B] = 0.20 M, rate = 0.0020 M/s."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_255dc041e26047', 'les_ba5e448d9ff34f', 'learn', 3, 'definition', '{"term":"Integrated rate laws","body":"Zero order: $[A] = [A]_0 - kt$. First order: $\\ln[A] = \\ln[A]_0 - kt$, with constant half-life $t_{1/2} = \\frac{0.693}{k}$. Second order: $\\frac{1}{[A]} = \\frac{1}{[A]_0} + kt$. Whichever plot is a straight line reveals the order, and its slope gives k."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_293c167c6a458b', 'les_ba5e448d9ff34f', 'learn', 4, 'worked_example', '{"title":"A first-order reaction has k = 0.0231 min⁻¹","steps":[{"latex":"t_{1/2} = \\tfrac{0.693}{0.0231} = 30\\ \\text{min}","explanation":""},{"latex":"\\text{after 90 min: } \\left(\\tfrac12\\right)^3 = 12.5\\%\\ \\text{remains}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_554857b8d55f02', 'les_ba5e448d9ff34f', 'experiment', 5, 'activity', '{"activity":"kinetics","title":"Compare the three orders","params":{"order":"2","k":0.1,"A0":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9af3973f50f09d', 'les_ba5e448d9ff34f', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Drug dosing schedules come from first-order elimination half-lives; ozone depletion was traced through rate-law studies."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb8d7711902316', 'les_ba5e448d9ff34f', 1, 'practice', 'multiple_choice', 2, 'Tripling [A] increases the rate 9 times. The order in A is…', '{"choices":["1","2","3","0"],"answer":1}', '[]', '$3^2 = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b6b44bc8d3022', 'les_ba5e448d9ff34f', 2, 'practice', 'numeric', 2, 'Rate = k[A]² with k = 0.50 M⁻¹s⁻¹ and [A] = 0.20 M. Find the rate.', '{"answer":0.02,"tolerance":0.0001,"unit":"M/s"}', '[]', '$0.50(0.04)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_255dc041e26047', 'les_ba5e448d9ff34f', 3, 'practice', 'numeric', 3, 'A first-order reaction drops from 0.80 M to 0.20 M in 40 s. Find k, to three decimal places.', '{"answer":0.035,"tolerance":0.001,"unit":"s⁻¹"}', '[]', 'Two half-lives in 40 s: $t_{1/2} = 20$ s, $k = \frac{0.693}{20}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_293c167c6a458b', 'les_ba5e448d9ff34f', 4, 'review', 'multiple_choice', 3, 'A plot of ln[A] against t is a straight line. The reaction is…', '{"choices":["zero order","first order","second order","third order"],"answer":1}', '[]', 'Integrated first-order law.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ba5e448d9ff34f', (SELECT id FROM concepts WHERE slug = 'kinetics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ba5e448d9ff34f', (SELECT id FROM formulas WHERE slug = 'rate-laws'), 1);

-- Lesson: reaction-energy-profile
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d0f44995406e60', 'reaction-energy-profile', 'Reaction energy profile', 'Read activation energy, the transition state and ΔH from energy profiles, and use the Arrhenius equation to relate rate constants and temperature.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1ded321a84d6b8', 'les_d0f44995406e60', 1, 'Label reactants, products, the transition state, Eₐ and ΔH on an energy profile.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c820da254de45f', 'les_d0f44995406e60', 2, 'Find the reverse activation energy: Eₐ(reverse) = Eₐ(forward) − ΔH.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0d647938221b6', 'les_d0f44995406e60', 3, 'Use the Arrhenius equation: ln(k₂/k₁) = (Eₐ/R)(1/T₁ − 1/T₂).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ded321a84d6b8', 'les_d0f44995406e60', 'learn', 1, 'definition', '{"term":"Energy profiles","body":"Potential energy along the reaction path rises from the reactants to a peak, the transition state (activated complex), then falls to the products. The rise is Eₐ; the overall difference is ΔH. For the reverse reaction, $E_a(\\text{rev}) = E_a(\\text{fwd}) - \\Delta H$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c820da254de45f', 'les_d0f44995406e60', 'learn', 2, 'definition', '{"term":"Arrhenius","body":"$k = Ae^{-E_a/RT}$, so $\\ln\\frac{k_2}{k_1} = \\frac{E_a}{R}\\left(\\frac{1}{T_1} - \\frac{1}{T_2}\\right)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0d647938221b6', 'les_d0f44995406e60', 'learn', 3, 'worked_example', '{"title":"A rate constant doubles from 298 K to 308 K. Find Eₐ","steps":[{"latex":"E_a = \\tfrac{R\\ln 2}{\\frac1{298} - \\frac1{308}}","explanation":""},{"latex":"E_a \\approx 52.9\\ \\text{kJ/mol}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e018ea286ef895', 'les_d0f44995406e60', 'experiment', 4, 'activity', '{"activity":"kinetics","title":"Temperature and Eₐ","params":{"order":"1","k":0.1,"A0":1,"temperature":308,"Ea":53}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_340ee424dec772', 'les_d0f44995406e60', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Food expiration testing at raised temperatures, and why fevers speed up metabolism."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ded321a84d6b8', 'les_d0f44995406e60', 1, 'practice', 'numeric', 2, 'Eₐ(forward) = 80 kJ/mol and ΔH = −30 kJ/mol. Find Eₐ(reverse).', '{"answer":110,"unit":"kJ/mol"}', '[]', '$80 - (-30)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c820da254de45f', 'les_d0f44995406e60', 2, 'practice', 'numeric', 3, 'k = 0.010 s⁻¹ at 300 K and Eₐ = 60 kJ/mol. Find k at 320 K, to three decimal places.', '{"answer":0.045,"tolerance":0.001,"unit":"s⁻¹"}', '[]', '$0.010\,e^{(60{,}000/8.314)(1/300 - 1/320)} \approx 0.045$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0d647938221b6', 'les_d0f44995406e60', 3, 'practice', 'multiple_choice', 2, 'On an energy profile, the transition state is at…', '{"choices":["the reactants","the highest point","the products","the lowest point"],"answer":1}', '[]', 'The top of the barrier.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e018ea286ef895', 'les_d0f44995406e60', 4, 'review', 'multiple_choice', 3, 'A larger Eₐ makes the rate constant…', '{"choices":["less sensitive to temperature","more sensitive to temperature","independent of temperature","negative"],"answer":1}', '[]', 'Eₐ multiplies the 1/T term.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d0f44995406e60', (SELECT id FROM concepts WHERE slug = 'kinetics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d0f44995406e60', (SELECT id FROM formulas WHERE slug = 'rate-laws'), 1);

-- Lesson: reaction-mechanisms
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c79b91a98aa79d', 'reaction-mechanisms', 'Introduction to reaction mechanisms', 'Check proposed mechanisms: steps must add to the overall reaction and the rate-determining step must match the observed rate law; handle intermediates and fast pre-equilibria.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a8abe0eecc16b1', 'les_c79b91a98aa79d', 1, 'Identify intermediates and confirm the steps add to the overall equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_60d670e53b6bc2', 'les_c79b91a98aa79d', 2, 'Derive the rate law from a slow first step.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b82b0796f3249f', 'les_c79b91a98aa79d', 3, 'Handle a fast pre-equilibrium by replacing the intermediate''s concentration.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8abe0eecc16b1', 'les_c79b91a98aa79d', 'learn', 1, 'definition', '{"term":"Mechanisms","body":"A mechanism is a sequence of elementary steps. Intermediates form in one step and are used up in a later one; they don''t appear in the overall equation. The slowest step (rate-determining) sets the rate law."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60d670e53b6bc2', 'les_c79b91a98aa79d', 'learn', 2, 'worked_example', '{"title":"NO₂ + CO → NO + CO₂, observed rate = k[NO₂]²","steps":[{"latex":"\\text{slow: } 2\\text{NO}_2 \\to \\text{NO}_3 + \\text{NO}","explanation":"Its rate law is k[NO₂]²."},{"latex":"\\text{fast: } \\text{NO}_3 + \\text{CO} \\to \\text{NO}_2 + \\text{CO}_2","explanation":"NO₃ is an intermediate."},{"latex":"\\text{sum: } \\text{NO}_2 + \\text{CO} \\to \\text{NO} + \\text{CO}_2","explanation":"Consistent with the data."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b82b0796f3249f', 'les_c79b91a98aa79d', 'learn', 3, 'definition', '{"term":"Fast pre-equilibrium","body":"If a fast reversible step comes first, express the intermediate through its equilibrium constant. For 2NO ⇌ N₂O₂ (fast), then N₂O₂ + O₂ → 2NO₂ (slow): $[\\text{N}_2\\text{O}_2] = K[\\text{NO}]^2$, so rate $= k_2K[\\text{NO}]^2[\\text{O}_2]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e00673de968690', 'les_c79b91a98aa79d', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Drug designers target the rate-determining step of enzyme mechanisms; chlorine radicals destroy ozone through a two-step catalytic mechanism."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a8abe0eecc16b1', 'les_c79b91a98aa79d', 1, 'practice', 'multiple_choice', 2, 'An intermediate…', '{"choices":["appears in the overall equation","forms and is then consumed","is a catalyst","is the slowest step"],"answer":1}', '[]', 'It never appears overall.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60d670e53b6bc2', 'les_c79b91a98aa79d', 2, 'practice', 'multiple_choice', 2, 'If the first step is slow and is A + B → C, the rate law is…', '{"choices":["k[A]","k[A][B]","k[C]","k[A]²"],"answer":1}', '[]', 'The rate-determining step''s molecularity.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b82b0796f3249f', 'les_c79b91a98aa79d', 3, 'practice', 'multiple_choice', 3, 'A mechanism is consistent with data if…', '{"choices":["it has many steps","the steps sum to the overall equation and predict the observed rate law","every step is slow","it has no intermediates"],"answer":1}', '[]', 'Consistent doesn''t mean proven.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e00673de968690', 'les_c79b91a98aa79d', 4, 'review', 'multiple_choice', 3, 'A catalyst in a mechanism…', '{"choices":["appears only as a product","is consumed in an early step and regenerated later","is an intermediate","slows the reaction"],"answer":1}', '[]', 'The opposite pattern from an intermediate.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c79b91a98aa79d', (SELECT id FROM concepts WHERE slug = 'kinetics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c79b91a98aa79d', (SELECT id FROM formulas WHERE slug = 'rate-laws'), 1);

-- Lesson: reaction-quotient
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6c7d70fe420dc3', 'reaction-quotient', 'Reaction quotient and equilibrium constant', 'Write Kc and Kp expressions (leaving out solids and liquids), compute the reaction quotient Q at any moment, and compare Q with K to predict the direction of change.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9a23fab0fe1c5b', 'les_6c7d70fe420dc3', 1, 'Write Kc and Kp expressions, omitting pure solids and liquids.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1ace7cb1070bad', 'les_6c7d70fe420dc3', 2, 'Compute Q from current concentrations or pressures.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_04cba0a3957eba', 'les_6c7d70fe420dc3', 3, 'Predict direction: Q < K goes forward, Q > K goes in reverse, Q = K is at equilibrium.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a23fab0fe1c5b', 'les_6c7d70fe420dc3', 'learn', 1, 'definition', '{"term":"Q and K","body":"Q has the same form as K but uses the current concentrations. For gases you can use partial pressures (Kp). Pure solids and liquids are left out: for CaCO₃(s) ⇌ CaO(s) + CO₂(g), $K_p = P_{\\text{CO}_2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ace7cb1070bad', 'les_6c7d70fe420dc3', 'learn', 2, 'worked_example', '{"title":"N₂ + 3H₂ ⇌ 2NH₃ with K = 0.50; currently [N₂] = 1.0, [H₂] = 1.0, [NH₃] = 0.50 M","steps":[{"latex":"Q = \\tfrac{(0.50)^2}{(1.0)(1.0)^3} = 0.25","explanation":""},{"latex":"Q < K \\Rightarrow \\text{shifts forward}","explanation":"More NH₃ will form."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04cba0a3957eba', 'les_6c7d70fe420dc3', 'experiment', 3, 'activity', '{"activity":"equilibrium","title":"Q right after a disturbance","params":{"K":4,"A0":1,"B0":1,"amount":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10d0fd4d8c64b3', 'les_6c7d70fe420dc3', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Chemists check Q against K to decide whether a mixture in a reactor will keep producing product or run backward."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9a23fab0fe1c5b', 'les_6c7d70fe420dc3', 1, 'practice', 'numeric', 2, 'For H₂ + I₂ ⇌ 2HI (K = 49), [H₂] = [I₂] = 0.20 M and [HI] = 1.0 M. Find Q.', '{"answer":25}', '[]', '$\frac{1.0}{0.04}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ace7cb1070bad', 'les_6c7d70fe420dc3', 2, 'practice', 'multiple_choice', 2, 'For that mixture, the reaction…', '{"choices":["is at equilibrium","shifts forward","shifts in reverse","stops"],"answer":1}', '[]', 'Q = 25 < 49.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04cba0a3957eba', 'les_6c7d70fe420dc3', 3, 'practice', 'multiple_choice', 2, 'Which goes into the K expression for Zn(s) + Cu²⁺(aq) ⇌ Zn²⁺(aq) + Cu(s)?', '{"choices":["[Zn][Cu²⁺]","[Zn²⁺]/[Cu²⁺]","[Cu]/[Zn]","[Zn²⁺][Cu]"],"answer":1}', '[]', 'Solids are left out.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10d0fd4d8c64b3', 'les_6c7d70fe420dc3', 4, 'review', 'multiple_choice', 3, 'If Q > K, then…', '{"choices":["more products form","products convert back to reactants","K increases","nothing happens"],"answer":1}', '[]', 'Too much product relative to equilibrium.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6c7d70fe420dc3', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6c7d70fe420dc3', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: reactions-particulate
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ed0032ff42a0c5', 'reactions-particulate', 'Introduction for reactions', 'Describe chemical reactions as rearrangements of atoms, interpret particle diagrams of reactions (including leftover reactant), and use evidence to identify a reaction.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_604ec3e39eddce', 'les_ed0032ff42a0c5', 1, 'Describe reactions as breaking and forming bonds with atoms conserved.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a2cefe4f13a829', 'les_ed0032ff42a0c5', 2, 'Interpret and draw particle diagrams before and after a reaction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_77a632632e982f', 'les_ed0032ff42a0c5', 3, 'Identify the limiting and excess reactants from a diagram.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_604ec3e39eddce', 'les_ed0032ff42a0c5', 'learn', 1, 'definition', '{"term":"Rearranging atoms","body":"A chemical reaction breaks bonds in the reactants and forms new ones in the products; the atoms themselves are conserved. Evidence (gas, precipitate, color or temperature change) suggests a reaction, but only new substances confirm it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2cefe4f13a829', 'les_ed0032ff42a0c5', 'learn', 2, 'worked_example', '{"title":"A diagram shows 6 H₂ and 4 O₂ molecules reacting: 2H₂ + O₂ → 2H₂O","steps":[{"latex":"6\\ \\text{H}_2\\ \\text{need}\\ 3\\ \\text{O}_2 \\Rightarrow 6\\ \\text{H}_2\\text{O}","explanation":"H₂ is limiting."},{"latex":"4 - 3 = 1\\ \\text{O}_2\\ \\text{left over}","explanation":"The after-picture must show 6 H₂O and 1 O₂."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_77a632632e982f', 'les_ed0032ff42a0c5', 'experiment', 3, 'activity', '{"activity":"stoichiometry","title":"Limiting reactant, particle by particle"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b368d98edb8829', 'les_ed0032ff42a0c5', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"AP free-response questions often ask you to draw or check particle diagrams, and engineers balance fuel–air mixtures the same way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_604ec3e39eddce', 'les_ed0032ff42a0c5', 1, 'practice', 'numeric', 2, 'N₂ + 3H₂ → 2NH₃. A diagram has 4 N₂ and 9 H₂. How many NH₃ can form?', '{"answer":6}', '[]', '9 H₂ make 6 NH₃ (using 3 N₂); H₂ is limiting.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2cefe4f13a829', 'les_ed0032ff42a0c5', 2, 'practice', 'numeric', 2, 'In that reaction, how many N₂ molecules are left over?', '{"answer":1}', '[]', '$4 - 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_77a632632e982f', 'les_ed0032ff42a0c5', 3, 'practice', 'multiple_choice', 2, 'Which observation alone proves a chemical reaction occurred?', '{"choices":["bubbles","a temperature change","a new substance with different properties","a color change"],"answer":2}', '[]', 'The others can happen physically.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b368d98edb8829', 'les_ed0032ff42a0c5', 4, 'review', 'multiple_choice', 3, 'In every chemical reaction, which is conserved?', '{"choices":["molecules","atoms","moles of substance","volume"],"answer":1}', '[]', 'Atoms rearrange; molecules change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ed0032ff42a0c5', (SELECT id FROM concepts WHERE slug = 'chemical-reactions'));

-- Lesson: real-gases
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1a6382a2d8e48a', 'real-gases', 'Deviation from ideal gas law', 'Explain when and why real gases deviate from PV = nRT, and use the van der Waals equation to correct for particle volume and attractions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bafa55c61c3455', 'les_1a6382a2d8e48a', 1, 'Identify the conditions (high pressure, low temperature) where gases deviate from ideal behavior.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_30cc653f962fab', 'les_1a6382a2d8e48a', 2, 'Explain the effects of particle volume and intermolecular attraction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e7787a0b75a78c', 'les_1a6382a2d8e48a', 3, 'Use the van der Waals equation for a real-gas pressure.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bafa55c61c3455', 'les_1a6382a2d8e48a', 'learn', 1, 'definition', '{"term":"Two corrections","body":"Attractions pull particles away from the walls, so the real pressure is lower than ideal. At very high pressure, the particles'' own volume takes up space, so the real volume is larger than ideal. Both matter most at high pressure and low temperature, and for large, polar molecules."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30cc653f962fab', 'les_1a6382a2d8e48a', 'learn', 2, 'definition', '{"term":"van der Waals","body":"$\\left(P + \\frac{an^2}{V^2}\\right)(V - nb) = nRT$, where $a$ measures attractions and $b$ the particles'' size."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e7787a0b75a78c', 'les_1a6382a2d8e48a', 'learn', 3, 'worked_example', '{"title":"1.00 mol of CO₂ in 1.00 L at 300 K (a = 3.59 L²·atm/mol², b = 0.0427 L/mol)","steps":[{"latex":"P_{ideal} = \\tfrac{(1.00)(0.08206)(300)}{1.00} = 24.6\\ \\text{atm}","explanation":""},{"latex":"P_{vdW} = \\tfrac{24.6}{1.00 - 0.0427} - 3.59 \\approx 22.1\\ \\text{atm}","explanation":"Attractions dominate: about 10% lower."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd8d9a8308a46d', 'les_1a6382a2d8e48a', 'experiment', 4, 'activity', '{"activity":"ideal-gas","title":"The ideal baseline"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9284d884d0dc9c', 'les_1a6382a2d8e48a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"High-pressure gas cylinders, natural-gas pipelines and refrigerants all need real-gas corrections."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bafa55c61c3455', 'les_1a6382a2d8e48a', 1, 'practice', 'multiple_choice', 2, 'Which gas behaves most ideally at room conditions?', '{"choices":["NH₃","H₂O vapor","He","CO₂"],"answer":2}', '[]', 'Small and nonpolar.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30cc653f962fab', 'les_1a6382a2d8e48a', 2, 'practice', 'multiple_choice', 2, 'Real gases deviate most at…', '{"choices":["high T, low P","low T, high P","STP","in a vacuum"],"answer":1}', '[]', 'Particles are close and slow.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e7787a0b75a78c', 'les_1a6382a2d8e48a', 3, 'practice', 'numeric', 3, 'Find P_vdW for 1.00 mol of N₂ in 1.00 L at 300 K (a = 1.39, b = 0.0391), to one decimal place.', '{"answer":24.2,"tolerance":0.1,"unit":"atm"}', '[]', '$\frac{24.62}{0.9609} - 1.39 \approx 24.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd8d9a8308a46d', 'les_1a6382a2d8e48a', 4, 'review', 'multiple_choice', 3, 'When intermolecular attractions dominate, the measured pressure is…', '{"choices":["higher than ideal","lower than ideal","equal to ideal","zero"],"answer":1}', '[]', 'Particles hit the walls less hard.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1a6382a2d8e48a', (SELECT id FROM concepts WHERE slug = 'gas-laws'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1a6382a2d8e48a', (SELECT id FROM formulas WHERE slug = 'ideal-gas-law'), 1);

-- Lesson: representations-solutions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7cdee80e77baaa', 'representations-solutions', 'Representations of solutions', 'Draw and interpret particle diagrams of solutions, find ion concentrations of strong electrolytes, and show how water molecules orient around ions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c320de9bd13d7', 'les_7cdee80e77baaa', 1, 'Show ionic compounds dissociating in particle diagrams, with correct ion ratios.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_46533a1c9456e5', 'les_7cdee80e77baaa', 2, 'Find ion concentrations: [Cl⁻] in 0.10 M CaCl₂ is 0.20 M.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_46de0e7eae19b1', 'les_7cdee80e77baaa', 3, 'Orient water molecules around cations (O end) and anions (H end).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c320de9bd13d7', 'les_7cdee80e77baaa', 'learn', 1, 'definition', '{"term":"Particles in solution","body":"Strong electrolytes separate completely into ions: one CaCl₂ gives one Ca²⁺ and two Cl⁻. Molecular solutes (sugar) stay intact as molecules. A good diagram keeps ratios right and shows water''s partially negative O facing cations and its partially positive H facing anions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46533a1c9456e5', 'les_7cdee80e77baaa', 'learn', 2, 'worked_example', '{"title":"Ion concentrations in 0.10 M Al₂(SO₄)₃","steps":[{"latex":"[\\text{Al}^{3+}] = 2(0.10) = 0.20\\ \\text{M}","explanation":""},{"latex":"[\\text{SO}_4^{2-}] = 3(0.10) = 0.30\\ \\text{M}","explanation":"Total ions: 0.50 M."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46de0e7eae19b1', 'les_7cdee80e77baaa', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electrolyte drinks are designed by ion concentrations; conductivity meters measure total ions in water samples."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c320de9bd13d7', 'les_7cdee80e77baaa', 1, 'practice', 'numeric', 2, 'Find [NO₃⁻] in 0.25 M Ca(NO₃)₂.', '{"answer":0.5,"unit":"M"}', '[]', 'Two per formula unit.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46533a1c9456e5', 'les_7cdee80e77baaa', 2, 'practice', 'numeric', 2, '25.0 mL of 0.20 M NaCl is mixed with 25.0 mL of 0.10 M CaCl₂. Find [Cl⁻] in the mixture.', '{"answer":0.2,"unit":"M"}', '[]', '$\frac{0.005 + 0.005}{0.050}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46de0e7eae19b1', 'les_7cdee80e77baaa', 3, 'practice', 'multiple_choice', 2, 'Around a Na⁺ ion in water, water molecules point their…', '{"choices":["H atoms toward it","O atoms toward it","randomly","they don''t interact"],"answer":1}', '[]', 'O carries the partial negative charge.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f2535f410fd24c', 'les_7cdee80e77baaa', 4, 'review', 'multiple_choice', 3, 'A diagram of aqueous sugar should show…', '{"choices":["separate C, H and O atoms","intact sugar molecules","ions","a solid"],"answer":1}', '[]', 'Molecular solutes don''t dissociate.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7cdee80e77baaa', (SELECT id FROM concepts WHERE slug = 'solutions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7cdee80e77baaa', (SELECT id FROM formulas WHERE slug = 'molarity-dilution'), 1);

-- Lesson: solubility-equilibria
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4896171ba6b061', 'solubility-equilibria', 'Introduction to solubility equilibria', 'Write Ksp expressions, convert between Ksp and molar solubility, and predict precipitation by comparing Q with Ksp.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f107985f16a13a', 'les_4896171ba6b061', 1, 'Write Ksp expressions for slightly soluble salts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2720335936e960', 'les_4896171ba6b061', 2, 'Convert between Ksp and molar solubility s.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_067460e6dbb6d2', 'les_4896171ba6b061', 3, 'Predict whether a precipitate forms (Q > Ksp).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f107985f16a13a', 'les_4896171ba6b061', 'learn', 1, 'definition', '{"term":"Ksp","body":"For AgCl(s) ⇌ Ag⁺ + Cl⁻, $K_{sp} = [\\text{Ag}^+][\\text{Cl}^-]$ (the solid is left out). For CaF₂ ⇌ Ca²⁺ + 2F⁻, $K_{sp} = [\\text{Ca}^{2+}][\\text{F}^-]^2$. If s mol/L dissolves, then for AgCl $K_{sp} = s^2$ and for CaF₂ $K_{sp} = s(2s)^2 = 4s^3$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2720335936e960', 'les_4896171ba6b061', 'learn', 2, 'worked_example', '{"title":"AgCl (Ksp = 1.8 × 10⁻¹⁰) and CaF₂ (Ksp = 3.9 × 10⁻¹¹)","steps":[{"latex":"\\text{AgCl}: s = \\sqrt{1.8\\times10^{-10}} = 1.3\\times10^{-5}\\ \\text{M}","explanation":"About 1.9 mg per liter."},{"latex":"\\text{CaF}_2: s = \\sqrt[3]{\\tfrac{3.9\\times10^{-11}}{4}} = 2.1\\times10^{-4}\\ \\text{M}","explanation":"More soluble despite its smaller Ksp."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_067460e6dbb6d2', 'les_4896171ba6b061', 'learn', 3, 'definition', '{"term":"Predicting precipitation","body":"Compute Q from the ion concentrations after mixing. Q > Ksp: precipitate forms. Q < Ksp: no precipitate. Q = Ksp: saturated."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_686eb4fe59fd07', 'les_4896171ba6b061', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Kidney stones, hard-water scale, fluoride strengthening tooth enamel, and barium sulfate X-ray contrast (very low Ksp, so safe)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f107985f16a13a', 'les_4896171ba6b061', 1, 'practice', 'numeric', 2, 'BaSO₄ has s = 1.05 × 10⁻⁵ M. Find Ksp, in units of $10^{-10}$, to one decimal place.', '{"answer":1.1,"tolerance":0.01}', '[]', '$s^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2720335936e960', 'les_4896171ba6b061', 2, 'practice', 'numeric', 3, 'Find the molar solubility of Ag₂CrO₄ (Ksp = 1.1 × 10⁻¹²), in units of $10^{-5}$ M, to one decimal place.', '{"answer":6.5,"tolerance":0.1}', '[]', '$4s^3 = 1.1\times10^{-12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_067460e6dbb6d2', 'les_4896171ba6b061', 3, 'practice', 'multiple_choice', 2, 'Equal volumes of 0.010 M Pb(NO₃)₂ and 0.020 M KI are mixed (PbI₂ Ksp = 9.8 × 10⁻⁹). A precipitate…', '{"choices":["forms, because Q = 5 × 10⁻⁷ > Ksp","doesn''t form","forms only when heated","can''t be predicted"],"answer":0}', '[]', 'After mixing: 0.0050 M Pb²⁺ and 0.010 M I⁻; $Q = 0.005(0.01)^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_686eb4fe59fd07', 'les_4896171ba6b061', 4, 'review', 'multiple_choice', 3, 'Comparing solubilities with Ksp alone is valid only when the salts…', '{"choices":["have the same ion ratio","are both chlorides","have similar mass","are colorless"],"answer":0}', '[]', 'Different formulas give different s expressions.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4896171ba6b061', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4896171ba6b061', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: spectroscopy-em
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e96e32038004ba', 'spectroscopy-em', 'Spectroscopy and the electromagnetic spectrum', 'Match regions of the electromagnetic spectrum to the molecular transitions they cause, and compute photon energies per photon and per mole.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1e0fd56de36c57', 'les_e96e32038004ba', 1, 'Match microwave, infrared and UV-visible radiation to rotational, vibrational and electronic transitions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ab8d9a62bc6d0', 'les_e96e32038004ba', 2, 'Compute photon energy E = hc/λ, per photon and per mole.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1232163a55f15d', 'les_e96e32038004ba', 3, 'Decide whether a photon has enough energy to break a bond.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1e0fd56de36c57', 'les_e96e32038004ba', 'learn', 1, 'definition', '{"term":"What absorbs what","body":"Microwaves change molecular rotation; infrared changes bond vibration (the basis of IR spectroscopy and the greenhouse effect); visible and UV light move electrons to higher energy levels; high-energy UV and X-rays can break bonds and ionize."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ab8d9a62bc6d0', 'les_e96e32038004ba', 'learn', 2, 'worked_example', '{"title":"254 nm UV light","steps":[{"latex":"E = \\tfrac{(6.626\\times10^{-34})(3.00\\times10^8)}{254\\times10^{-9}}","explanation":""},{"latex":"E = 7.83\\times10^{-19}\\ \\text{J}","explanation":"Per photon."},{"latex":"\\times 6.022\\times10^{23} \\approx 471\\ \\text{kJ/mol}","explanation":"More than a C–C bond (347 kJ/mol), which is why UV sterilizes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1232163a55f15d', 'les_e96e32038004ba', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Microwave ovens spin water molecules; IR spectra identify functional groups; UV lamps disinfect water; sunscreen absorbs UV before it reaches skin."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1e0fd56de36c57', 'les_e96e32038004ba', 1, 'practice', 'multiple_choice', 2, 'Infrared radiation mainly causes…', '{"choices":["electronic transitions","bond vibrations","molecular rotation","ionization"],"answer":1}', '[]', 'IR spectroscopy measures vibrations.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ab8d9a62bc6d0', 'les_e96e32038004ba', 2, 'practice', 'numeric', 2, 'Find the energy per mole of 600 nm photons, to the nearest kJ/mol.', '{"answer":199,"tolerance":1,"unit":"kJ/mol"}', '[]', '$\frac{hc}{600\ \text{nm}}N_A \approx 199$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1232163a55f15d', 'les_e96e32038004ba', 3, 'practice', 'multiple_choice', 2, 'Which radiation is energetic enough to break a 400 kJ/mol bond?', '{"choices":["microwave","infrared","red light (650 nm)","UV at 250 nm"],"answer":3}', '[]', 'About 479 kJ/mol.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4f28ca2b7ee735', 'les_e96e32038004ba', 4, 'review', 'multiple_choice', 3, 'Greenhouse gases warm the planet because they absorb…', '{"choices":["visible light","infrared radiation","UV","radio waves"],"answer":1}', '[]', 'Their bonds vibrate at IR frequencies.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e96e32038004ba', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e96e32038004ba', (SELECT id FROM formulas WHERE slug = 'photon-energy'), 1);

-- Lesson: states-phase-diagrams
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_80ba5d8bceabc4', 'states-phase-diagrams', 'Solids, liquids and gases', 'Compare the particle arrangements of solids, liquids and gases, explain vapor pressure and boiling, and read phase diagrams.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b77963aeb5762', 'les_80ba5d8bceabc4', 1, 'Compare particle spacing, motion and order in the three states.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8f01c070d55bf3', 'les_80ba5d8bceabc4', 2, 'Explain vapor pressure, and boiling as vapor pressure equal to external pressure.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2babea458f45b6', 'les_80ba5d8bceabc4', 3, 'Read a phase diagram: triple point, critical point and phase boundaries.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b77963aeb5762', 'les_80ba5d8bceabc4', 'learn', 1, 'definition', '{"term":"Particle view","body":"Solids: particles in fixed positions, vibrating. Liquids: close together but able to slide past each other. Gases: far apart, moving freely. Stronger intermolecular forces keep substances condensed to higher temperatures."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f01c070d55bf3', 'les_80ba5d8bceabc4', 'learn', 2, 'definition', '{"term":"Vapor pressure","body":"Molecules escape from a liquid''s surface until evaporation and condensation balance; the pressure of that vapor is the vapor pressure, which rises with temperature and is lower when IMFs are stronger. A liquid boils when its vapor pressure equals the surrounding pressure: water boils at about 70 °C on Mount Everest."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2babea458f45b6', 'les_80ba5d8bceabc4', 'learn', 3, 'definition', '{"term":"Phase diagrams","body":"Pressure against temperature, with lines where two phases coexist. At the triple point all three coexist; beyond the critical point, liquid and gas become one supercritical fluid. Water''s solid–liquid line slopes left, so pressure can melt ice. For CO₂, the triple point is above 1 atm, so dry ice sublimes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3aae774d6fdcf', 'les_80ba5d8bceabc4', 'learn', 4, 'worked_example', '{"title":"Reading a diagram: what happens to ice at −10 °C as pressure rises far enough?","steps":[{"latex":"\\text{cross the solid–liquid line}","explanation":"It melts: unusual, because ice is less dense than water."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_acb3a3f93a7d66', 'les_80ba5d8bceabc4', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pressure cookers raise the boiling point to cook faster; supercritical CO₂ decaffeinates coffee."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b77963aeb5762', 'les_80ba5d8bceabc4', 1, 'practice', 'multiple_choice', 2, 'Which liquid has the highest vapor pressure at 25 °C?', '{"choices":["water","ethanol","diethyl ether","glycerol"],"answer":2}', '[]', 'Weakest IMFs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8f01c070d55bf3', 'les_80ba5d8bceabc4', 2, 'practice', 'multiple_choice', 2, 'At high altitude, water boils at a lower temperature because…', '{"choices":["water is different there","the outside pressure is lower","IMFs are weaker","the air is colder"],"answer":1}', '[]', 'Vapor pressure needs only to match a lower pressure.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2babea458f45b6', 'les_80ba5d8bceabc4', 3, 'practice', 'multiple_choice', 2, 'At the triple point,…', '{"choices":["only gas exists","solid, liquid and gas coexist","the liquid is supercritical","nothing boils"],"answer":1}', '[]', 'Three phase lines meet.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d3aae774d6fdcf', 'les_80ba5d8bceabc4', 4, 'review', 'multiple_choice', 3, 'Dry ice sublimes at 1 atm because CO₂''s triple point is…', '{"choices":["below 1 atm","above 1 atm","at 0 °C","nonexistent"],"answer":1}', '[]', 'Liquid CO₂ only exists above 5.1 atm.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_80ba5d8bceabc4', (SELECT id FROM concepts WHERE slug = 'kinetic-molecular-theory'));

-- Lesson: thermal-equilibrium-chem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b52fe067da7e23', 'thermal-equilibrium-chem', 'Heat transfer and thermal equilibrium', 'Explain heat transfer between objects in particle terms, and solve for final temperatures and specific heats when substances reach thermal equilibrium.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_59f89109d372e8', 'les_b52fe067da7e23', 1, 'Explain heat flow as transfer of kinetic energy in particle collisions, from hot to cold.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e6283315078fc0', 'les_b52fe067da7e23', 2, 'Use q_lost = −q_gained to find a final temperature.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_802a3385f875a6', 'les_b52fe067da7e23', 3, 'Find an unknown specific heat from mixing data.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_59f89109d372e8', 'les_b52fe067da7e23', 'learn', 1, 'definition', '{"term":"Particle picture","body":"Faster particles in the hotter object collide with slower ones in the cooler object, transferring kinetic energy until the average kinetic energies, and so the temperatures, are equal: thermal equilibrium."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6283315078fc0', 'les_b52fe067da7e23', 'learn', 2, 'worked_example', '{"title":"50.0 g of aluminum (c = 0.897 J/(g·°C)) at 100.0 °C is dropped into 100.0 g of water at 20.0 °C","steps":[{"latex":"44.85(T - 100) + 418.4(T - 20) = 0","explanation":"Heat lost + heat gained = 0, with mc = 50.0(0.897) and 100.0(4.184)."},{"latex":"T = \\tfrac{4485 + 8368}{44.85 + 418.4} \\approx 27.7\\ °\\text{C}","explanation":"Water''s large heat capacity keeps T low."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_802a3385f875a6', 'les_b52fe067da7e23', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Coffee-cup calorimetry, engine cooling systems, and why coastal cities have mild climates."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_59f89109d372e8', 'les_b52fe067da7e23', 1, 'practice', 'numeric', 3, 'A 30.0 g metal at 95.0 °C is put in 50.0 g of water at 22.0 °C; the final temperature is 25.0 °C. Find the metal''s specific heat, to three decimal places.', '{"answer":0.299,"tolerance":0.002,"unit":"J/(g·°C)"}', '[]', '$c = \frac{50.0(4.184)(3.0)}{30.0(70.0)} \approx 0.299$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e6283315078fc0', 'les_b52fe067da7e23', 2, 'practice', 'numeric', 2, '100 g of water at 80 °C mixes with 100 g at 20 °C. Find the final temperature.', '{"answer":50,"unit":"°C"}', '[]', 'Equal masses, same c: the average.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_802a3385f875a6', 'les_b52fe067da7e23', 3, 'practice', 'multiple_choice', 2, 'Heat flows from A to B until…', '{"choices":["A is empty of energy","both reach the same temperature","both have the same heat","B is hotter"],"answer":1}', '[]', 'Thermal equilibrium.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_207b5705fa1975', 'les_b52fe067da7e23', 4, 'review', 'multiple_choice', 3, 'At thermal equilibrium, which is equal for both objects?', '{"choices":["total thermal energy","average kinetic energy of particles","mass","specific heat"],"answer":1}', '[]', 'Temperature measures it.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b52fe067da7e23', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b52fe067da7e23', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: types-chemical-bonds
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bbe2c8a1a826d7', 'types-chemical-bonds', 'Types of chemical bonds', 'Classify bonds as nonpolar covalent, polar covalent, ionic or metallic using electronegativity, and connect bond type to the particles involved.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5c7105dbf3810f', 'les_bbe2c8a1a826d7', 1, 'Use electronegativity differences to place bonds on a continuum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_220c1b7e892d88', 'les_bbe2c8a1a826d7', 2, 'Describe ionic, covalent and metallic bonding at the particle level.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_319201e30f3e39', 'les_bbe2c8a1a826d7', 3, 'Identify partial charges (δ+, δ−) in polar bonds.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5c7105dbf3810f', 'les_bbe2c8a1a826d7', 'learn', 1, 'definition', '{"term":"A continuum","body":"Bond character depends on the electronegativity difference Δχ: about 0 gives nonpolar covalent (Cl₂), intermediate gives polar covalent (HCl, Δχ = 0.96, with δ− on Cl), and large gives mostly ionic (NaCl, Δχ = 2.23). Between metals, valence electrons are delocalized: metallic bonding."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_220c1b7e892d88', 'les_bbe2c8a1a826d7', 'learn', 2, 'worked_example', '{"title":"Rank O–H, C–H and Na–O by polarity (χ: O 3.44, H 2.20, C 2.55, Na 0.93)","steps":[{"latex":"\\Delta\\chi:\\ 1.24,\\ 0.35,\\ 2.51","explanation":""},{"latex":"\\text{C–H} < \\text{O–H} < \\text{Na–O}","explanation":"Na–O is essentially ionic."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_319201e30f3e39', 'les_bbe2c8a1a826d7', 'learn', 3, 'callout', '{"tone":"note","title":"Exceptions","body":"Bond type is a model. Real bonds have mixed character, and AP questions usually ask you to justify a classification with electronegativity and the kinds of elements involved."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c3ef426ad12af', 'les_bbe2c8a1a826d7', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Bond polarity sets solubility, boiling points and how drugs bind to proteins."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5c7105dbf3810f', 'les_bbe2c8a1a826d7', 1, 'practice', 'numeric', 2, 'Find Δχ for a C–O bond (C 2.55, O 3.44), to two decimal places.', '{"answer":0.89,"tolerance":0.001}', '[]', 'Polar covalent.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_220c1b7e892d88', 'les_bbe2c8a1a826d7', 2, 'practice', 'multiple_choice', 2, 'Which bond is most polar?', '{"choices":["C–C","C–N","C–F","C–H"],"answer":2}', '[]', 'F is the most electronegative element.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_319201e30f3e39', 'les_bbe2c8a1a826d7', 3, 'practice', 'multiple_choice', 2, 'In H–Cl, the partial negative charge is on…', '{"choices":["H","Cl","both","neither"],"answer":1}', '[]', 'Cl is more electronegative.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c3ef426ad12af', 'les_bbe2c8a1a826d7', 4, 'review', 'multiple_choice', 3, 'Which describes bonding in copper metal?', '{"choices":["shared pairs between two atoms","transferred electrons","cations in a sea of delocalized electrons","hydrogen bonds"],"answer":2}', '[]', 'Metallic bonding.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bbe2c8a1a826d7', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: weak-acids-ka
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0cf9288624702d', 'weak-acids-ka', 'Weak acids, weak bases and Ka', 'Write Ka and Kb expressions, compute the pH of weak acid and base solutions with ICE tables, find percent ionization, and use KaKb = Kw.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a1c1fc7bbd8508', 'les_0cf9288624702d', 1, 'Write Ka and Kb expressions and relate them by KaKb = Kw.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a495732053df1', 'les_0cf9288624702d', 2, 'Compute the pH of weak acid and weak base solutions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a598470cbc3303', 'les_0cf9288624702d', 3, 'Compute percent ionization and explain how it changes with dilution.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a1c1fc7bbd8508', 'les_0cf9288624702d', 'learn', 1, 'definition', '{"term":"Ka","body":"For HA ⇌ H⁺ + A⁻, $K_a = \\frac{[\\text{H}^+][\\text{A}^-]}{[\\text{HA}]}$. A larger Ka means a stronger acid; $\\text{p}K_a = -\\log K_a$. For a weak base, $K_b = \\frac{[\\text{BH}^+][\\text{OH}^-]}{[\\text{B}]}$, and for a conjugate pair $K_aK_b = K_w = 1.0\\times10^{-14}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a495732053df1', 'les_0cf9288624702d', 'learn', 2, 'worked_example', '{"title":"pH of 0.10 M acetic acid (Ka = 1.8 × 10⁻⁵)","steps":[{"latex":"\\tfrac{x^2}{0.10 - x} = 1.8\\times10^{-5},\\ x \\ll 0.10","explanation":""},{"latex":"x = \\sqrt{1.8\\times10^{-6}} = 1.34\\times10^{-3}\\ \\text{M}","explanation":"1.3% of 0.10: the approximation is fine."},{"latex":"\\text{pH} = 2.87","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a598470cbc3303', 'les_0cf9288624702d', 'learn', 3, 'worked_example', '{"title":"pH of 0.10 M ammonia (Kb = 1.8 × 10⁻⁵)","steps":[{"latex":"[\\text{OH}^-] = 1.34\\times10^{-3} \\Rightarrow \\text{pOH} = 2.87","explanation":""},{"latex":"\\text{pH} = 14 - 2.87 = 11.13","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2732224384219b', 'les_0cf9288624702d', 'experiment', 4, 'activity', '{"activity":"titration","title":"Weak acid at the start of a titration","params":{"acid":"weak","acidConc":0.1,"baseConc":0.1,"baseVolume":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c8ba8cb3e64f22', 'les_0cf9288624702d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Vinegar, citric acid and the carbonic acid in blood are weak acids; aspirin''s pKa decides where in your digestive tract it''s absorbed."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a1c1fc7bbd8508', 'les_0cf9288624702d', 1, 'practice', 'numeric', 2, 'Find the pH of 0.050 M HF (Ka = 6.8 × 10⁻⁴), solving exactly. Two decimal places.', '{"answer":2.26,"tolerance":0.01}', '[]', '$x^2 + 6.8\times10^{-4}x - 3.4\times10^{-5} = 0$ gives $x \approx 5.5\times10^{-3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a495732053df1', 'les_0cf9288624702d', 2, 'practice', 'numeric', 2, 'Find Kb of acetate (acetic acid Ka = 1.8 × 10⁻⁵), in units of $10^{-10}$, to two decimal places.', '{"answer":5.56,"tolerance":0.01}', '[]', '$\frac{10^{-14}}{1.8\times10^{-5}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a598470cbc3303', 'les_0cf9288624702d', 3, 'practice', 'numeric', 3, 'Find the percent ionization of 0.010 M acetic acid, to one decimal place.', '{"answer":4.2,"tolerance":0.1,"unit":"%"}', '[]', '$x = \sqrt{1.8\times10^{-7}} = 4.24\times10^{-4}$, about 4.2% (higher than at 0.10 M).');
